export { AIBuilder } from '@/components/formedible/ai/ai-builder';
export { AgentSettings } from '@/components/formedible/ai/agent-settings';
export { AiFormRenderer, parseAiToFormedible } from '@/components/formedible/ai/ai-form-renderer';
export { ChatInterface, generateAiFormCode } from '@/components/formedible/ai/chat-interface';
export { ConversationHistory } from '@/components/formedible/ai/conversation-history';
export { ParserSettings } from '@/components/formedible/ai/parser-settings';
export { createDefaultProviderSecrets, createDefaultProviderSettings, providerOptions, ProviderSelection, validateProviderAccess } from '@/components/formedible/ai/provider-selection';
export { SidebarContent } from '@/components/formedible/ai/sidebar-content';
export { SidebarIcons } from '@/components/formedible/ai/sidebar-icons';
export { createTanStackTextAdapter, DEFAULT_TANSTACK_AI_MODELS, SUPPORTED_TANSTACK_AI_PROVIDERS } from '@/lib/formedible/ai-adapters';
export { normalizePersistedAiMessage, normalizePersistedAiMessages, toPersistedAiMessage, toTanStackMessageInput, toTanStackMessageInputs, toTanStackSystemPrompts } from '@/lib/formedible/ai-messages';
export { extractFormCode } from '@/lib/formedible/ai-parser';
export { canUseStorage, clearConversations, clearStoredProviderSecrets, createConversation, exportConversation, getLastFormCode, persistConversations, persistProviderSecrets, persistProviderSettings, persistUiState, readJson, readPersistedAIBuilderState, readStoredProviderSecrets, STORAGE_KEYS, upsertConversation, writeJson } from '@/lib/formedible/ai-storage';
export type { AnthropicAdapterModel, OpenAIAdapterModel, OpenRouterAdapterModel } from '@/lib/formedible/ai-adapters';
export type { PersistedAiMessage, TanStackAiMessageInput } from '@/lib/formedible/ai-messages';
export type { PersistedAIBuilderState, PersistedUiState, ProviderSecretPersistencePreference, ProviderSecretStorageMode, StorageArea, StoredProviderSecrets } from '@/lib/formedible/ai-storage';
export type {
  AiConversationMetadata,
  AiConversation,
  AiConversationExport,
  AiErrorInfo,
  AiFinishReason,
  AiFormParseResult,
  AiGenerationMetadata,
  AiGenerationRequest,
  AiGenerationResult,
  AiJsonValue,
  AiMessage,
  AiMessagePart,
  AiMessageRole,
  AiMessageStatus,
  AIBuilderMode,
  AiParserConfig,
  AiParseError,
  AiRawOutput,
  AiStreamEvent,
  AiThinkingOutput,
  AiToolChunk,
  AiUsageMetadata,
  GeneratedFormSnapshot,
  ProviderSecrets,
  ProviderSettings,
} from '@/lib/formedible/ai-types';

'use client';

import { useEffect, useRef, useState } from 'react';

import { AiFormRenderer } from '@/components/formedible/ai/ai-form-renderer';
import { AgentSettings } from '@/components/formedible/ai/agent-settings';
import { ChatInterface } from '@/components/formedible/ai/chat-interface';
import { createDefaultProviderSecrets, createDefaultProviderSettings, ProviderSelection, validateProviderAccess } from '@/components/formedible/ai/provider-selection';
import { SidebarContent } from '@/components/formedible/ai/sidebar-content';
import { SidebarIcons, type SidebarView } from '@/components/formedible/ai/sidebar-icons';
import { Button } from '@/components/ui/button';
import { clearStoredProviderSecrets, exportConversation, getLastFormCode, persistConversations, persistProviderSecrets, persistProviderSettings, persistUiState, readPersistedAIBuilderState, readStoredProviderSecrets, upsertConversation } from '@/lib/formedible/ai-storage';
import type { ProviderSecretPersistencePreference } from '@/lib/formedible/ai-storage';
import type { AiConversation, AiMessage, AiParserConfig, AIBuilderMode, ProviderSecrets, ProviderSettings } from '@/lib/formedible/ai-types';
import { defaultParserConfig, generateSystemPrompt, mergeParserConfig } from '@/lib/formedible/parser-config-schema';
import type { ParserConfig } from '@/lib/formedible/parser-config-schema';
import type { FormedibleFormValues } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

export const AI_BUILDER_DEFAULT_MODE: AIBuilderMode = 'client';

export interface AIBuilderProps {
  readonly className?: string;
  readonly mode?: AIBuilderMode;
  readonly providerSettings?: ProviderSettings;
  readonly providerSecrets?: ProviderSecrets;
  readonly onProviderSettingsChange?: (providerSettings: ProviderSettings) => void;
  readonly onProviderSecretsChange?: (providerSecrets: ProviderSecrets) => void;
  readonly onFormGenerated?: (formCode: string) => void;
  readonly onFormSubmit?: (formData: FormedibleFormValues) => void | Promise<void>;
}

export interface AIBuilderProviderAccess {
  readonly settings: ProviderSettings;
  readonly secrets: ProviderSecrets;
}

function readProviderSecretPersistencePreference(): ProviderSecretPersistencePreference {
  return readStoredProviderSecrets('session')?.preference ?? readStoredProviderSecrets('local')?.preference ?? { mode: 'memory', rememberKey: false };
}

function toAiParserConfig(config: ParserConfig): AiParserConfig {
  return {
    strictValidation: config.strictValidation,
    inferDefaultValues: config.enableSchemaInference,
    ...(config.selectFields ? { allowedFieldTypes: config.systemPromptFields } : {}),
  };
}

export function resolveInitialProviderAccess(
  controlledProviderSettings?: ProviderSettings,
  controlledProviderSecrets?: ProviderSecrets,
): AIBuilderProviderAccess {
  const persistedState = readPersistedAIBuilderState(createDefaultProviderSettings(), controlledProviderSettings);
  const settings = persistedState.providerSettings;
  const storedSecrets = readStoredProviderSecrets('session')?.secrets ?? readStoredProviderSecrets('local')?.secrets;
  const secrets = controlledProviderSecrets && controlledProviderSecrets.provider === settings.provider
    ? controlledProviderSecrets
    : storedSecrets && storedSecrets.provider === settings.provider
      ? storedSecrets
    : createDefaultProviderSecrets(settings.provider);

  return { settings, secrets };
}

export function AIBuilder({
  className,
  mode = AI_BUILDER_DEFAULT_MODE,
  providerSettings: controlledProviderSettings,
  providerSecrets: controlledProviderSecrets,
  onProviderSettingsChange,
  onProviderSecretsChange,
  onFormGenerated,
  onFormSubmit,
}: AIBuilderProps) {
  const [internalProviderAccess, setInternalProviderAccess] = useState<AIBuilderProviderAccess>(() => resolveInitialProviderAccess(controlledProviderSettings, controlledProviderSecrets));
  const [providerSecretPersistence, setProviderSecretPersistence] = useState<ProviderSecretPersistencePreference>(() => readProviderSecretPersistencePreference());
  const [parserConfig, setParserConfig] = useState<ParserConfig>(() => mergeParserConfig(defaultParserConfig));
  const [conversations, setConversations] = useState<readonly AiConversation[]>(() => readPersistedAIBuilderState(createDefaultProviderSettings()).conversations);
  const [currentConversationId, setCurrentConversationId] = useState<string | undefined>(() => readPersistedAIBuilderState(createDefaultProviderSettings()).currentConversationId);
  const [activeSidebarView, setActiveSidebarView] = useState<SidebarView | null>('history');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const currentConversationIdRef = useRef<string | undefined>(currentConversationId);
  const providerSettings = controlledProviderSettings ?? internalProviderAccess.settings;
  const providerSecrets = controlledProviderSecrets ?? (internalProviderAccess.secrets.provider === providerSettings.provider ? internalProviderAccess.secrets : createDefaultProviderSecrets(providerSettings.provider));
  const currentConversation = conversations.find((conversation) => conversation.id === currentConversationId);
  const messages = currentConversation?.messages ?? [];
  const formCode = currentConversation?.formCode ?? getLastFormCode(messages);
  const providerValidationError = mode === 'client' ? validateProviderAccess(providerSettings, providerSecrets) : undefined;
  const systemPrompt = generateSystemPrompt(parserConfig);
  const aiParserConfig = toAiParserConfig(parserConfig);

  useEffect(() => {
    if (!controlledProviderSettings) {
      persistProviderSettings(internalProviderAccess.settings);
    }
  }, [controlledProviderSettings, internalProviderAccess.settings]);

  useEffect(() => {
    if (!controlledProviderSecrets) {
      persistProviderSecrets(internalProviderAccess.secrets, providerSecretPersistence);
    }
  }, [controlledProviderSecrets, internalProviderAccess.secrets, providerSecretPersistence]);

  useEffect(() => {
    if (controlledProviderSecrets || internalProviderAccess.secrets.provider === providerSettings.provider) {
      return;
    }

    setInternalProviderAccess((previousAccess) => ({
      ...previousAccess,
      secrets: createDefaultProviderSecrets(providerSettings.provider),
    }));
  }, [controlledProviderSecrets, internalProviderAccess.secrets.provider, providerSettings.provider]);

  useEffect(() => {
    persistConversations(conversations);
  }, [conversations]);

  useEffect(() => {
    currentConversationIdRef.current = currentConversationId;
    persistUiState(currentConversationId ? { currentConversationId } : {});
  }, [currentConversationId]);

  function updateProviderAccess(nextSettings: ProviderSettings, nextSecrets: ProviderSecrets) {
    setInternalProviderAccess({ settings: nextSettings, secrets: nextSecrets });
    onProviderSettingsChange?.(nextSettings);
    onProviderSecretsChange?.(nextSecrets);
  }

  function updateProviderSecretPersistence(nextPreference: ProviderSecretPersistencePreference) {
    setProviderSecretPersistence(nextPreference);
  }

  function clearProviderSecrets() {
    clearStoredProviderSecrets();
    updateProviderAccess(providerSettings, createDefaultProviderSecrets(providerSettings.provider));
  }

  function updateMessages(nextMessages: readonly AiMessage[]) {
    setConversations((previousConversations) => {
      const result = upsertConversation(previousConversations, currentConversationIdRef.current, nextMessages);
      currentConversationIdRef.current = result.conversationId;
      setCurrentConversationId(result.conversationId);

      return result.conversations;
    });
  }

  function updateFormCode(nextFormCode: string) {
    const activeConversationId = currentConversationIdRef.current;
    setConversations((previousConversations) => previousConversations.map((conversationEntry) => (conversationEntry.id === activeConversationId ? { ...conversationEntry, formCode: nextFormCode, updatedAt: Date.now() } : conversationEntry)));
    onFormGenerated?.(nextFormCode);
  }

  function startNewConversation() {
    currentConversationIdRef.current = undefined;
    setCurrentConversationId(undefined);
  }

  function selectConversation(conversationId: string) {
    currentConversationIdRef.current = conversationId;
    setCurrentConversationId(conversationId);
  }

  function deleteConversation(conversationId: string) {
    setConversations((previousConversations) => {
      const nextConversations = previousConversations.filter((conversation) => conversation.id !== conversationId);

      if (currentConversationIdRef.current === conversationId) {
        const nextCurrentConversationId = nextConversations.at(-1)?.id;
        currentConversationIdRef.current = nextCurrentConversationId;
        setCurrentConversationId(nextCurrentConversationId);
      }

      return nextConversations;
    });
  }

  function downloadConversation(conversation: AiConversation) {
    if (typeof document === 'undefined' || typeof URL === 'undefined') {
      return;
    }

    const exportedConversation = exportConversation(conversation);
    const fileName = `${conversation.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'formedible-conversation'}.json`;
    const blob = new Blob([JSON.stringify(exportedConversation, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.href = url;
    link.download = fileName;
    link.rel = 'noopener';
    document.body.append(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  }

  function toggleSidebarCollapse() {
    setIsSidebarCollapsed((previousValue) => !previousValue);
  }

  return (
    <section className={cn('flex min-h-[640px] overflow-hidden rounded-lg border bg-background', className)} data-conversation-id={currentConversationId ?? 'new'}>
      <SidebarIcons isCollapsed={isSidebarCollapsed} activeView={activeSidebarView} onToggleCollapse={toggleSidebarCollapse} onViewChange={setActiveSidebarView} />
      <SidebarContent
        activeView={activeSidebarView}
        isCollapsed={isSidebarCollapsed}
        conversations={conversations}
        currentConversation={currentConversation}
        currentConversationId={currentConversationId}
          providerSettings={providerSettings}
          providerSecrets={providerSecrets}
          providerSecretPersistence={providerSecretPersistence}
          parserConfig={parserConfig}
          onProviderAccessChange={updateProviderAccess}
          onProviderSecretPersistenceChange={updateProviderSecretPersistence}
          onClearProviderSecrets={clearProviderSecrets}
          onParserConfigChange={setParserConfig}
        onSelectConversation={selectConversation}
        onDeleteConversation={deleteConversation}
        onNewConversation={startNewConversation}
        onExportConversation={downloadConversation}
      />
      <div className="grid min-w-0 flex-1 gap-4 p-4 lg:grid-cols-[minmax(0,0.95fr)_minmax(360px,1.05fr)]">
        <div className="flex min-h-0 flex-col gap-4">
          {isSidebarCollapsed ? <div className="grid gap-3"><ProviderSelection settings={providerSettings} secrets={providerSecrets} persistencePreference={providerSecretPersistence} onChange={updateProviderAccess} onPersistencePreferenceChange={updateProviderSecretPersistence} onClearStoredSecrets={clearProviderSecrets} /><AgentSettings settings={providerSettings} secrets={providerSecrets} onChange={updateProviderAccess} /></div> : null}
          {providerValidationError ? <p className="rounded-md border border-destructive/40 p-2 text-sm text-destructive">{providerValidationError}</p> : null}
          <div className="flex items-center justify-between gap-2 rounded-lg border p-2">
            <p className="truncate text-sm text-muted-foreground">{currentConversation ? currentConversation.title : 'New conversation'}</p>
            <Button type="button" variant="outline" size="sm" onClick={startNewConversation}>New conversation</Button>
          </div>
          <ChatInterface
            providerSettings={providerSettings}
            providerSecrets={providerSecrets}
            mode={mode}
            messages={messages}
            onMessagesChange={updateMessages}
            onFormGenerated={updateFormCode}
            conversationId={currentConversationId}
            systemPrompt={systemPrompt}
            parserConfig={aiParserConfig}
            className="min-h-[420px]"
          />
        </div>
        <div className="min-h-0 rounded-lg border p-4">
          {formCode ? (
            <AiFormRenderer code={formCode} parserConfig={aiParserConfig} onSubmit={onFormSubmit} className="space-y-4" />
          ) : (
            <div className="flex h-full min-h-[320px] items-center justify-center text-sm text-muted-foreground">Generated forms appear here.</div>
          )}
        </div>
      </div>
    </section>
  );
}

export type { AiConversation, AIBuilderMode, ProviderSecrets, ProviderSettings } from '@/lib/formedible/ai-types';
export { STORAGE_KEYS } from '@/lib/formedible/ai-storage';

'use client';

import { Input } from '@/components/ui/input';
import type { ProviderSecrets, ProviderSettings } from '@/lib/formedible/ai-types';
import { cn } from '@/lib/utils';

export interface AgentSettingsProps {
  readonly settings: ProviderSettings;
  readonly secrets: ProviderSecrets;
  readonly onChange: (settings: ProviderSettings, secrets: ProviderSecrets) => void;
  readonly className?: string;
}

function parseOptionalNumber(value: string): number | undefined {
  if (value.trim() === '') {
    return undefined;
  }

  const parsedValue = Number(value);
  return Number.isFinite(parsedValue) ? parsedValue : undefined;
}

function updateThinkingBudget(settings: ProviderSettings, thinkingBudgetTokens: number | undefined): ProviderSettings {
  if (settings.provider !== 'anthropic') {
    return settings;
  }

  if (thinkingBudgetTokens === undefined) {
    const { thinkingBudgetTokens: _thinkingBudgetTokens, ...nextSettings } = settings;
    return nextSettings;
  }

  return { ...settings, thinkingBudgetTokens };
}

function updateTemperature(settings: ProviderSettings, temperature: number | undefined): ProviderSettings {
  if (temperature === undefined) {
    const { temperature: _temperature, ...nextSettings } = settings;
    return nextSettings;
  }

  return { ...settings, temperature };
}

function updateMaxTokens(settings: ProviderSettings, maxTokens: number | undefined): ProviderSettings {
  if (maxTokens === undefined) {
    const { maxTokens: _maxTokens, ...nextSettings } = settings;
    return nextSettings;
  }

  return { ...settings, maxTokens };
}

export function AgentSettings({ settings, secrets, onChange, className }: AgentSettingsProps) {
  return (
    <section className={cn('grid gap-3 rounded-lg border bg-background p-3', className)} aria-labelledby="ai-builder-agent-settings-title">
      <div>
        <h2 id="ai-builder-agent-settings-title" className="text-sm font-semibold">Model settings</h2>
        <p className="mt-1 text-xs text-muted-foreground">Tune the active TanStack AI adapter without enabling custom endpoints.</p>
      </div>
      <label className="grid gap-1 text-sm font-medium">
        Model
        <Input value={settings.model} onChange={(event) => onChange({ ...settings, model: event.target.value }, secrets)} />
      </label>
      <div className="grid gap-3 sm:grid-cols-2">
        <label className="grid gap-1 text-sm font-medium">
          Temperature
          <Input value={settings.temperature ?? ''} type="number" min="0" max="2" step="0.1" onChange={(event) => onChange(updateTemperature(settings, parseOptionalNumber(event.target.value)), secrets)} />
        </label>
        <label className="grid gap-1 text-sm font-medium">
          Max tokens
          <Input value={settings.maxTokens ?? ''} type="number" min="1" step="1" onChange={(event) => onChange(updateMaxTokens(settings, parseOptionalNumber(event.target.value)), secrets)} />
        </label>
      </div>
      {settings.provider === 'anthropic' ? (
        <label className="grid gap-1 text-sm font-medium">
          Thinking budget tokens
          <Input value={settings.thinkingBudgetTokens ?? ''} type="number" min="1" step="1" onChange={(event) => onChange(updateThinkingBudget(settings, parseOptionalNumber(event.target.value)), secrets)} />
          <span className="text-xs font-normal text-muted-foreground">Anthropic-only reasoning budget. Leave empty to omit the option.</span>
        </label>
      ) : (
        <p className="rounded-md border border-dashed p-2 text-xs text-muted-foreground">Thinking budget controls are only available for Anthropic models.</p>
      )}
    </section>
  );
}

'use client';

import { useEffect, useState } from 'react';

import { useFormedible } from '@/hooks/use-formedible';
import { parseAiToFormedible } from '@/lib/formedible/ai-parser';
import type { AiFormParseResult, AiParserConfig } from '@/lib/formedible/ai-types';
import type { FormedibleFormValues, UseFormedibleOptions } from '@/lib/formedible/types';

export interface AiFormRendererProps {
  readonly code: string;
  readonly isStreaming?: boolean;
  readonly onParseComplete?: (result: AiFormParseResult) => void;
  readonly onSubmit?: (formData: FormedibleFormValues) => void | Promise<void>;
  readonly className?: string;
  readonly parserConfig?: AiParserConfig;
}

function EmptyForm({ className, message }: { readonly className?: string; readonly message: string }) {
  return <div className={className}>{message}</div>;
}

function ParsedForm({ className, options }: { readonly className?: string; readonly options: UseFormedibleOptions<FormedibleFormValues> }) {
  const { Form } = useFormedible(options);

  return <Form className={className} />;
}

export function AiFormRenderer({ code, isStreaming, onParseComplete, onSubmit, className, parserConfig }: AiFormRendererProps) {
  const [parseResult, setParseResult] = useState<AiFormParseResult>(() =>
    isStreaming ? { schema: undefined, formOptions: { fields: [], formOptions: { defaultValues: {} } }, success: false } : parseAiToFormedible(code, parserConfig),
  );

  useEffect(() => {
    if (isStreaming) {
      return;
    }

    const nextResult = parseAiToFormedible(code, parserConfig);
    setParseResult(nextResult);
    onParseComplete?.(nextResult);
  }, [code, isStreaming, onParseComplete, parserConfig]);

  if (isStreaming) {
    return <EmptyForm className={className} message="Waiting for the generated form..." />;
  }

  if (!parseResult.success) {
    return <EmptyForm className={className} message={parseResult.error ?? 'Generated form could not be parsed.'} />;
  }

  const options: UseFormedibleOptions<FormedibleFormValues> = {
    ...parseResult.formOptions,
    formOptions: {
      ...parseResult.formOptions.formOptions,
      onSubmit: async ({ value }) => {
        await parseResult.formOptions.formOptions.onSubmit?.({ value });
        await onSubmit?.(value);
      },
    },
  };

  return <ParsedForm className={className} options={options} />;
}

export { parseAiToFormedible } from '@/lib/formedible/ai-parser';
export type { AiFormParseResult, AiParserConfig } from '@/lib/formedible/ai-types';

'use client';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import type { AIProvider, ProviderSecrets, ProviderSettings } from '@/lib/formedible/ai-types';
import type { ProviderSecretPersistencePreference, ProviderSecretStorageMode } from '@/lib/formedible/ai-storage';
import { cn } from '@/lib/utils';

export const providerOptions = [
  { value: 'openai', label: 'OpenAI', defaultModel: 'gpt-4o-mini', requiresKey: true },
  { value: 'anthropic', label: 'Anthropic', defaultModel: 'claude-sonnet-4-5', requiresKey: true },
  { value: 'openrouter', label: 'OpenRouter', defaultModel: 'openai/gpt-4o-mini', requiresKey: true },
] as const satisfies readonly { readonly value: AIProvider; readonly label: string; readonly defaultModel: string; readonly requiresKey: boolean }[];

export interface ProviderSelectionProps {
  readonly settings: ProviderSettings;
  readonly secrets: ProviderSecrets;
  readonly onChange: (settings: ProviderSettings, secrets: ProviderSecrets) => void;
  readonly persistencePreference?: ProviderSecretPersistencePreference;
  readonly onPersistencePreferenceChange?: (preference: ProviderSecretPersistencePreference) => void;
  readonly onClearStoredSecrets?: () => void;
  readonly className?: string;
}

const defaultPersistencePreference: ProviderSecretPersistencePreference = {
  mode: 'memory',
  rememberKey: false,
};

export function createDefaultProviderSettings(provider: AIProvider = 'openai'): ProviderSettings {
  const option = providerOptions.find((entry) => entry.value === provider) ?? providerOptions[0];

  return {
    provider: option.value,
    model: option.defaultModel,
    temperature: 0.7,
    maxTokens: 4000,
  };
}

export function createDefaultProviderSecrets(provider: AIProvider = 'openai'): ProviderSecrets {
  return {
    provider,
    apiKey: '',
  };
}

export function validateProviderAccess(settings: ProviderSettings | null, secrets: ProviderSecrets | null): string | undefined {
  if (!settings) {
    return 'Provider settings are required.';
  }

  if (!secrets) {
    return 'Provider secrets are required.';
  }

  const provider = providerOptions.find((entry) => entry.value === settings.provider);

  if (!provider) {
    return 'Unsupported AI provider.';
  }

  if (settings.provider !== secrets.provider) {
    return 'Provider settings and secrets must target the same provider.';
  }

  if ('endpoint' in settings || 'baseURL' in settings) {
    return 'Custom provider endpoints are not supported. Select OpenAI, Anthropic, or OpenRouter without endpoint/baseURL overrides.';
  }

  if (settings.provider !== 'anthropic' && 'thinkingBudgetTokens' in settings) {
    return 'Thinking budget tokens are only supported for Anthropic.';
  }

  if (provider.requiresKey && secrets.apiKey.trim().length === 0) {
    return `API key is required for ${provider.label}.`;
  }

  return undefined;
}

function isAIProvider(value: string | null): value is AIProvider {
  if (value === null) {
    return false;
  }

  return providerOptions.some((provider) => provider.value === value);
}

function isProviderSecretStorageMode(value: string | null): value is ProviderSecretStorageMode {
  return value === 'memory' || value === 'session' || value === 'local';
}

export function ProviderSelection({ settings, secrets, onChange, persistencePreference = defaultPersistencePreference, onPersistencePreferenceChange, onClearStoredSecrets, className }: ProviderSelectionProps) {
  return (
    <section className={cn('grid gap-3 rounded-lg border bg-background p-3', className)} aria-labelledby="ai-builder-provider-settings-title">
      <div>
        <h2 id="ai-builder-provider-settings-title" className="text-sm font-semibold">Provider credentials</h2>
        <p className="mt-1 text-xs text-muted-foreground">Bring your own key. Keys stay in this browser, are never exported with conversations, and local storage requires an explicit opt-in.</p>
      </div>
      <label className="grid gap-1 text-sm font-medium">
        Provider
        <Select
          value={settings.provider}
          onValueChange={(providerValue) => {
            const provider = isAIProvider(providerValue) ? providerValue : providerOptions[0].value;
            const nextProvider = providerOptions.find((entry) => entry.value === provider) ?? providerOptions[0];
            onChange(createDefaultProviderSettings(nextProvider.value), { provider: nextProvider.value, apiKey: '' });
          }}
        >
          <SelectTrigger>
            <SelectValue placeholder="Select provider" />
          </SelectTrigger>
          <SelectContent>
            {providerOptions.map((provider) => (
              <SelectItem key={provider.value} value={provider.value}>
                {provider.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </label>
      <label className="grid gap-1 text-sm font-medium">
        API key
        <Input value={secrets.apiKey} type="password" autoComplete="off" placeholder={`${providerOptions.find((provider) => provider.value === settings.provider)?.label ?? 'Provider'} API key`} onChange={(event) => onChange(settings, { ...secrets, apiKey: event.target.value })} />
      </label>
      <div className="grid gap-3">
        <label className="grid gap-1 text-sm font-medium">
          Key storage
          <Select
            value={persistencePreference.mode}
            onValueChange={(modeValue) => {
              const mode = isProviderSecretStorageMode(modeValue) ? modeValue : 'memory';
              onPersistencePreferenceChange?.({
                mode,
                rememberKey: mode === 'memory' ? false : persistencePreference.rememberKey,
              });
            }}
          >
            <SelectTrigger>
              <SelectValue placeholder="Select storage mode" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="memory">Memory only</SelectItem>
              <SelectItem value="session">Session storage</SelectItem>
              <SelectItem value="local">Local storage</SelectItem>
            </SelectContent>
          </Select>
        </label>
        {persistencePreference.mode === 'local' ? (
          <p className="rounded-md border border-amber-500/40 bg-amber-500/10 p-2 text-xs text-amber-700 dark:text-amber-300">Local storage keeps the key on this device after the tab closes. Only use it on a trusted machine.</p>
        ) : null}
        <label className="flex items-start gap-2 rounded-md border p-2 text-sm font-medium">
          <input
            className="mt-1"
            type="checkbox"
            checked={persistencePreference.rememberKey}
            disabled={persistencePreference.mode === 'memory'}
            onChange={(event) => onPersistencePreferenceChange?.({ ...persistencePreference, rememberKey: event.target.checked })}
          />
          <span>
            Remember API key
            <span className="block text-xs font-normal text-muted-foreground">Disabled for memory-only mode. Session storage forgets the key when the browser session ends.</span>
          </span>
        </label>
      </div>
      <Button type="button" variant="outline" size="sm" onClick={onClearStoredSecrets}>Wipe stored key</Button>
    </section>
  );
}

'use client';

import { useState } from 'react';

import { ChatMessages } from '@/components/formedible/ai/chat-messages';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { collectAiGenerationResult, streamAiResponse } from '@/lib/formedible/ai-generation';
import { extractFormCode, parseAiToFormedible } from '@/lib/formedible/ai-parser';
import { createAiStreamScheduler } from '@/lib/formedible/ai-stream-scheduler';
import type {
  AiGenerationRequest,
  AiGenerationResult,
  AiFinishReason,
  AiMessage,
  AiParserConfig,
  AIBuilderMode,
  AiStreamEvent,
  ProviderSecrets,
  ProviderSettings,
} from '@/lib/formedible/ai-types';
import { cn } from '@/lib/utils';

export interface ChatInterfaceProps {
  readonly providerSettings: ProviderSettings | null;
  readonly providerSecrets: ProviderSecrets | null;
  readonly mode: AIBuilderMode;
  readonly messages: readonly AiMessage[];
  readonly onMessagesChange: (messages: readonly AiMessage[]) => void;
  readonly onFormGenerated?: (formCode: string) => void;
  readonly conversationId?: string;
  readonly systemPrompt?: string;
  readonly parserConfig?: AiParserConfig;
  readonly className?: string;
}

export const DEFAULT_AI_SYSTEM_PROMPT = 'You are Formedible AI Builder. Return a valid Formedible form configuration in a fenced formedible code block when generating or changing a form.';

function createMessage(role: AiMessage['role'], content: string, formCode?: string): AiMessage {
  return {
    id: `${role}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
    role,
    content,
    formCode,
    timestamp: Date.now(),
  };
}

export async function generateAiFormCode(
  request: AiGenerationRequest,
  mode: AIBuilderMode,
  abortController?: AbortController,
): Promise<AiGenerationResult> {
  if (mode === 'client') {
    if (!request.providerSettings) {
      throw new Error('Provider settings are required.');
    }

    if (!request.providerSecrets) {
      throw new Error('Provider secrets are required.');
    }

    return collectAiGenerationResult(request, { abortController });
  }

  throw new Error('AI Builder requires client mode to generate a form.');
}

export function resolveMessageStatus(finishReason: AiFinishReason | undefined, errors: readonly AiStreamEvent[]): AiMessage['status'] {
  if (finishReason === 'abort') {
    return 'aborted';
  }

  if (finishReason === 'error' || errors.some((event) => event.type === 'error')) {
    return 'error';
  }

  return 'completed';
}

export function ChatInterface({
  providerSettings,
  providerSecrets,
  mode,
  messages,
  onMessagesChange,
  onFormGenerated,
  conversationId,
  systemPrompt = DEFAULT_AI_SYSTEM_PROMPT,
  parserConfig,
  className,
}: ChatInterfaceProps) {
  const [prompt, setPrompt] = useState('');
  const [error, setError] = useState<string>();
  const [isGenerating, setIsGenerating] = useState(false);
  const [abortController, setAbortController] = useState<AbortController>();

  async function submitPrompt() {
    const trimmedPrompt = prompt.trim();

    if (!trimmedPrompt || isGenerating) {
      return;
    }

    const userMessage = createMessage('user', trimmedPrompt);
    const nextMessages = [...messages, userMessage];
    const assistantMessage: AiMessage = {
      ...createMessage('assistant', ''),
      status: 'streaming',
      provider: providerSettings?.provider,
      model: providerSettings?.model,
    };
    let displayedMessages: readonly AiMessage[] = [...nextMessages, assistantMessage];
    let streamedContent = '';
    let streamedThinking = '';
    let streamedEvents: AiStreamEvent[] = [];
    let finishReason: AiFinishReason | undefined;

    function updateAssistantMessage(message: AiMessage): void {
      displayedMessages = displayedMessages.map((existingMessage) => (existingMessage.id === assistantMessage.id ? message : existingMessage));
      onMessagesChange(displayedMessages);
    }

    onMessagesChange(displayedMessages);
    setPrompt('');
    setError(undefined);
    setIsGenerating(true);
    const nextAbortController = new AbortController();
    setAbortController(nextAbortController);
    const streamScheduler = createAiStreamScheduler((flush) => {
      streamedContent += flush.textDelta;
      streamedThinking += flush.thinkingDelta;
      streamedEvents = [...streamedEvents, ...flush.events];
      updateAssistantMessage({
        ...assistantMessage,
        content: streamedContent,
        rawContent: streamedContent,
        thinking: streamedThinking.length > 0 ? streamedThinking : undefined,
        events: streamedEvents,
        status: 'streaming',
      });
    });

    try {
      if (mode !== 'client') {
        throw new Error('AI Builder requires client mode to generate a form.');
      }

      const startedAt = Date.now();
      const request: AiGenerationRequest = { prompt: trimmedPrompt, providerSettings, providerSecrets, messages: nextMessages, systemPrompt, userMessage, conversationId };

      for await (const event of streamAiResponse(request, { abortController: nextAbortController })) {
        if (event.type === 'finish') {
          finishReason = event.finishReason;
        }

        if (event.type === 'error') {
          finishReason = 'error';
          setError(event.error.message);
        }

        streamScheduler.enqueue(event);
      }

      streamScheduler.flushNow();
      const finalStatus = resolveMessageStatus(finishReason, streamedEvents);
      const formCode = finalStatus === 'completed' ? extractFormCode(streamedContent) : undefined;
      const parseResult = formCode ? parseAiToFormedible(formCode, parserConfig) : undefined;
      const finishedAt = Date.now();
      const finalAssistantMessage: AiMessage = {
        ...assistantMessage,
        content: streamedContent,
        rawContent: streamedContent,
        thinking: streamedThinking.length > 0 ? streamedThinking : undefined,
        events: streamedEvents,
        formCode,
        formConfig: parseResult?.success ? parseResult.formOptions : undefined,
        parseErrors: parseResult?.success === false ? parseResult.errors : undefined,
        provider: providerSettings?.provider,
        model: providerSettings?.model,
        generation: providerSettings
          ? {
              provider: providerSettings.provider,
              model: providerSettings.model,
              finishReason,
              startedAt,
              finishedAt,
            }
          : undefined,
        status: finalStatus,
      };

      updateAssistantMessage(finalAssistantMessage);

      if (formCode) {
        onFormGenerated?.(formCode);
      }
    } catch (generationError) {
      streamScheduler.flushNow();
      const wasAborted = nextAbortController.signal.aborted;

      if (!wasAborted) {
        setError(generationError instanceof Error ? generationError.message : String(generationError));
      }

      updateAssistantMessage({
        ...assistantMessage,
        content: streamedContent,
        rawContent: streamedContent,
        thinking: streamedThinking.length > 0 ? streamedThinking : undefined,
        events: streamedEvents,
        provider: providerSettings?.provider,
        model: providerSettings?.model,
        generation: providerSettings
          ? {
              provider: providerSettings.provider,
              model: providerSettings.model,
              finishReason: wasAborted ? 'abort' : 'error',
              finishedAt: Date.now(),
            }
          : undefined,
        status: wasAborted ? 'aborted' : 'error',
      });
    } finally {
      streamScheduler.flushNow();
      setIsGenerating(false);
      setAbortController(undefined);
    }
  }

  return (
    <div className={cn('flex h-full flex-col gap-3', className)}>
      <div className="min-h-0 flex-1 space-y-3 overflow-auto rounded-lg border p-3">
        <ChatMessages messages={messages} />
      </div>
      {error ? <p className="rounded-md border border-destructive/40 p-2 text-sm text-destructive">{error}</p> : null}
      <div className="grid gap-2">
        <Textarea
          value={prompt}
          onChange={(event) => setPrompt(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === 'Enter' && !event.shiftKey) {
              event.preventDefault();
              void submitPrompt();
            }
          }}
          placeholder="Create a multi-step onboarding form..."
        />
        <div className="flex gap-2">
          <Button type="button" disabled={isGenerating || prompt.trim().length === 0} onClick={submitPrompt}>
            {isGenerating ? 'Generating...' : 'Generate form'}
          </Button>
          {isGenerating ? (
            <Button type="button" variant="outline" onClick={() => abortController?.abort('User stopped generation')}>
              Stop
            </Button>
          ) : null}
        </div>
      </div>
    </div>
  );
}

export type { AiGenerationRequest, AiGenerationResult, AiMessage } from '@/lib/formedible/ai-types';

'use client';

import { Bot, User } from 'lucide-react';

import { MarkdownMessage } from '@/components/formedible/ai/markdown-message';
import { RawOutputPanel } from '@/components/formedible/ai/raw-output-panel';
import type { AiMessage } from '@/lib/formedible/ai-types';
import { cn } from '@/lib/utils';

export interface ChatMessagesProps {
  readonly messages: readonly AiMessage[];
  readonly className?: string;
}

function MessageIcon({ role }: { readonly role: AiMessage['role'] }) {
  if (role === 'user') {
    return <User className="h-4 w-4" aria-hidden="true" />;
  }

  return <Bot className="h-4 w-4" aria-hidden="true" />;
}

function renderStatus(message: AiMessage): string | undefined {
  if (message.status === 'streaming') {
    return 'Streaming';
  }

  if (message.status === 'aborted') {
    return 'Aborted';
  }

  if (message.status === 'error') {
    return 'Error';
  }

  return undefined;
}

export function ChatMessages({ messages, className }: ChatMessagesProps) {
  if (messages.length === 0) {
    return <p className={cn('text-sm text-muted-foreground', className)}>Describe the form you want to build.</p>;
  }

  return (
    <div className={cn('space-y-3', className)}>
      {messages.map((message) => {
        const status = renderStatus(message);
        const isAssistant = message.role === 'assistant';

        return (
          <article key={message.id} className={cn('rounded-lg p-3 text-sm', message.role === 'user' ? 'bg-muted' : 'border bg-background')}>
            <div className="mb-2 flex items-center justify-between gap-3">
              <p className="flex items-center gap-2 font-medium capitalize">
                <MessageIcon role={message.role} />
                {message.role}
              </p>
              {status ? <span className="rounded-full bg-muted px-2 py-0.5 text-xs text-muted-foreground">{status}</span> : null}
            </div>
            {message.thinking ? (
              <details className="mb-3 rounded-md border bg-muted/30 p-2">
                <summary className="cursor-pointer text-xs font-medium text-muted-foreground">Thinking</summary>
                <p className="mt-2 whitespace-pre-wrap text-xs text-muted-foreground">{message.thinking}</p>
              </details>
            ) : null}
            {isAssistant ? <MarkdownMessage content={message.content} /> : <p className="whitespace-pre-wrap">{message.content}</p>}
            {isAssistant ? <RawOutputPanel message={message} className="mt-3" /> : null}
          </article>
        );
      })}
    </div>
  );
}

'use client';

import { Download, MessageSquare, Plus, Trash2 } from 'lucide-react';

import { Button } from '@/components/ui/button';
import type { AiConversation } from '@/lib/formedible/ai-types';
