export interface ConversationHistoryProps {
  readonly conversations: readonly AiConversation[];
  readonly currentConversationId?: string;
  readonly onSelectConversation: (conversationId: string) => void;
  readonly onDeleteConversation: (conversationId: string) => void;
  readonly onNewConversation: () => void;
  readonly onExportConversation: (conversation: AiConversation) => void;
  readonly className?: string;
}

function formatConversationTime(updatedAt: number): string {
  const hoursSinceUpdate = (Date.now() - updatedAt) / (1000 * 60 * 60);

  if (hoursSinceUpdate < 1) {
    return 'Just now';
  }

  if (hoursSinceUpdate < 24) {
    return `${Math.floor(hoursSinceUpdate)}h ago`;
  }

  return new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' }).format(new Date(updatedAt));
}

function getConversationTitle(conversation: AiConversation): string {
  const firstUserMessage = conversation.messages.find((message) => message.role === 'user');
  const title = conversation.title || firstUserMessage?.content || 'New conversation';

  return title.length > 64 ? `${title.slice(0, 61)}...` : title;
}

export function ConversationHistory({ conversations, currentConversationId, onSelectConversation, onDeleteConversation, onNewConversation, onExportConversation, className }: ConversationHistoryProps) {
  return (
    <section className={cn('flex h-full min-h-0 flex-col rounded-lg border bg-background', className)} aria-labelledby="ai-builder-history-title">
      <header className="flex items-center justify-between gap-3 border-b p-3">
        <div>
          <h2 id="ai-builder-history-title" className="text-sm font-semibold">History</h2>
          <p className="text-xs text-muted-foreground">{conversations.length} saved conversations</p>
        </div>
        <Button type="button" variant="outline" size="sm" onClick={onNewConversation} className="gap-1">
          <Plus className="h-3.5 w-3.5" aria-hidden="true" />
          New
        </Button>
      </header>
      <div className="min-h-0 flex-1 overflow-auto p-2">
        {conversations.length === 0 ? (
          <div className="flex h-full min-h-48 flex-col items-center justify-center rounded-md border border-dashed p-6 text-center text-muted-foreground">
            <MessageSquare className="mb-2 h-8 w-8 opacity-50" aria-hidden="true" />
            <p className="text-sm font-medium">No conversations yet</p>
            <p className="text-xs">Start a chat and it will appear here.</p>
          </div>
        ) : (
          <ul className="space-y-1">
            {conversations.map((conversation) => {
              const isActive = conversation.id === currentConversationId;

              return (
                <li key={conversation.id} className={cn('group rounded-md border border-transparent', isActive && 'border-border bg-muted/70')}>
                  <div className="flex items-center gap-2 p-2">
                    <button type="button" className="min-w-0 flex-1 text-left" onClick={() => onSelectConversation(conversation.id)} aria-current={isActive ? 'true' : undefined}>
                      <span className="block truncate text-sm font-medium">{getConversationTitle(conversation)}</span>
                      <span className="block text-xs text-muted-foreground">{formatConversationTime(conversation.updatedAt)} · {conversation.messages.length} messages</span>
                    </button>
                    <div className="flex shrink-0 items-center gap-1 opacity-100 sm:opacity-0 sm:transition-opacity sm:group-hover:opacity-100 sm:group-focus-within:opacity-100">
                      <Button type="button" variant="ghost" size="icon" className="h-7 w-7" onClick={() => onExportConversation(conversation)} aria-label={`Export ${getConversationTitle(conversation)}`}>
                        <Download className="h-3.5 w-3.5" aria-hidden="true" />
                      </Button>
                      <Button type="button" variant="ghost" size="icon" className="h-7 w-7 text-destructive hover:text-destructive" onClick={() => onDeleteConversation(conversation.id)} aria-label={`Delete ${getConversationTitle(conversation)}`}>
                        <Trash2 className="h-3.5 w-3.5" aria-hidden="true" />
                      </Button>
                    </div>
                  </div>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </section>
  );
}

'use client';

import { Check, Copy } from 'lucide-react';
import { Children, isValidElement, useState } from 'react';
import ReactMarkdown from 'react-markdown';
import rehypeHighlight from 'rehype-highlight';
import remarkGfm from 'remark-gfm';
import type { Components } from 'react-markdown';
import type { ReactNode } from 'react';

import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

export interface MarkdownMessageProps {
  readonly content: string;
  readonly className?: string;
}

interface CodeBlockProps {
  readonly code: string;
  readonly language?: string;
  readonly className?: string;
  readonly children: ReactNode;
}

function normalizeCode(children: ReactNode): string {
  return extractTextContent(children).replace(/\n$/, '');
}

function extractTextContent(children: ReactNode): string {
  return Children.toArray(children).map((child) => {
    if (typeof child === 'string' || typeof child === 'number') {
      return String(child);
    }

    if (isValidElement<{ readonly children?: ReactNode }>(child)) {
      return extractTextContent(child.props.children);
    }

    return '';
  }).join('');
}

function CodeBlock({ code, language, className, children }: CodeBlockProps) {
  const [copied, setCopied] = useState(false);

  async function copyCode() {
    if (typeof navigator === 'undefined' || !navigator.clipboard) {
      return;
    }

    await navigator.clipboard.writeText(code);
    setCopied(true);
    globalThis.setTimeout(() => setCopied(false), 1200);
  }

  return (
    <div className="group my-3 overflow-hidden rounded-lg border bg-muted/40">
      <div className="flex items-center justify-between border-b bg-muted/60 px-3 py-2 text-xs text-muted-foreground">
        <span>{language ?? 'text'}</span>
        <Button type="button" variant="ghost" size="sm" className="h-7 gap-1 px-2" onClick={copyCode} aria-label="Copy code block">
          {copied ? <Check className="h-3.5 w-3.5" aria-hidden="true" /> : <Copy className="h-3.5 w-3.5" aria-hidden="true" />}
          {copied ? 'Copied' : 'Copy'}
        </Button>
      </div>
      <pre className="overflow-x-auto p-3 text-sm leading-relaxed">
        <code className={cn(className, language ? `language-${language}` : undefined)}>{children}</code>
      </pre>
    </div>
  );
}

const markdownComponents = {
  a({ children, href, ...props }) {
    return (
      <a href={href} target="_blank" rel="noreferrer" className="font-medium underline underline-offset-4" {...props}>
        {children}
      </a>
    );
  },
  code({ children, className, ...props }) {
    const languageMatch = /language-([\w-]+)/.exec(className ?? '');
    const code = normalizeCode(children);

    if (languageMatch) {
      return <CodeBlock code={code} language={languageMatch[1]} className={className}>{children}</CodeBlock>;
    }

    return (
      <code className={cn('rounded bg-muted px-1 py-0.5 text-[0.9em]', className)} {...props}>
        {children}
      </code>
    );
  },
  table({ children, ...props }) {
    return (
      <div className="my-3 overflow-x-auto">
        <table className="w-full border-collapse text-sm" {...props}>
          {children}
        </table>
      </div>
    );
  },
  th({ children, ...props }) {
    return (
      <th className="border px-2 py-1 text-left font-semibold" {...props}>
        {children}
      </th>
    );
  },
  td({ children, ...props }) {
    return (
      <td className="border px-2 py-1" {...props}>
        {children}
      </td>
    );
  },
} satisfies Components;

export function MarkdownMessage({ content, className }: MarkdownMessageProps) {
  return (
    <div className={cn('prose prose-sm max-w-none dark:prose-invert prose-pre:m-0 prose-pre:bg-transparent', className)}>
      <ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeHighlight]} components={markdownComponents} skipHtml>
        {content}
      </ReactMarkdown>
    </div>
  );
}

'use client';

import { useState } from 'react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { defaultParserConfig, generateSystemPrompt, mergeParserConfig, parserConfigFields, validateParserConfig } from '@/lib/formedible/parser-config-schema';
import type { ParserConfig } from '@/lib/formedible/parser-config-schema';
import { cn } from '@/lib/utils';

export interface ParserSettingsProps {
  readonly config: ParserConfig;
  readonly onChange: (config: ParserConfig) => void;
  readonly className?: string;
}

function parseNumber(value: string, fallback: number): number {
  const parsedValue = Number(value);
  return Number.isFinite(parsedValue) ? parsedValue : fallback;
}

function configLabel(name: string): string {
  const field = parserConfigFields.find((entry) => entry.name === name);
  return typeof field?.label === 'string' ? field.label : name;
}

function updateConfig(config: ParserConfig, patch: Partial<ParserConfig>, onChange: (config: ParserConfig) => void): void {
  const nextConfig = mergeParserConfig({ ...config, ...patch });

  if (validateParserConfig(nextConfig)) {
    onChange(nextConfig);
  }
}

function toggleField(config: ParserConfig, field: string): ParserConfig {
  const selectedFields = config.systemPromptFields.includes(field)
    ? config.systemPromptFields.filter((entry) => entry !== field)
    : [...config.systemPromptFields, field];

  return mergeParserConfig({ ...config, systemPromptFields: selectedFields });
}

export function ParserSettings({ config, onChange, className }: ParserSettingsProps) {
  const [copied, setCopied] = useState(false);
  const systemPrompt = generateSystemPrompt(config);
  const fieldOptions = defaultParserConfig.systemPromptFields;

  async function copySystemPrompt(): Promise<void> {
    if (typeof navigator === 'undefined' || !navigator.clipboard) {
      return;
    }

    await navigator.clipboard.writeText(systemPrompt);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1200);
  }

  return (
    <section className={cn('grid gap-4 rounded-lg border bg-background p-3', className)} aria-labelledby="ai-builder-parser-settings-title">
      <div>
        <h2 id="ai-builder-parser-settings-title" className="text-sm font-semibold">Parser settings</h2>
        <p className="mt-1 text-xs text-muted-foreground">Control the synced Formedible parser contract and preview the system prompt sent to the model.</p>
      </div>
      <div className="grid gap-2">
        {(['strictValidation', 'enableSchemaInference', 'fieldTypeValidation', 'enableZodParsing', 'showDetailedErrors', 'selectFields', 'includeTabFormatting', 'includePageFormatting'] as const).map((key) => (
          <label key={key} className="flex items-start gap-2 rounded-md border p-2 text-sm font-medium">
            <input className="mt-1" type="checkbox" checked={Boolean(config[key])} onChange={(event) => updateConfig(config, { [key]: event.target.checked }, onChange)} />
            <span>{configLabel(key)}</span>
          </label>
        ))}
      </div>
      <label className="grid gap-1 text-sm font-medium">
        {configLabel('mergeStrategy')}
        <Select value={config.mergeStrategy} onValueChange={(value) => updateConfig(config, { mergeStrategy: value === 'override' || value === 'intersect' ? value : 'extend' }, onChange)}>
          <SelectTrigger>
            <SelectValue placeholder="Merge strategy" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="extend">Extend</SelectItem>
            <SelectItem value="override">Override</SelectItem>
            <SelectItem value="intersect">Intersect</SelectItem>
          </SelectContent>
        </Select>
      </label>
      <div className="grid gap-3 sm:grid-cols-2">
        <label className="grid gap-1 text-sm font-medium">
          {configLabel('maxCodeLength')}
          <Input type="number" min="1000" max="10000000" step="1000" value={config.maxCodeLength} onChange={(event) => updateConfig(config, { maxCodeLength: parseNumber(event.target.value, defaultParserConfig.maxCodeLength) }, onChange)} />
        </label>
        <label className="grid gap-1 text-sm font-medium">
          {configLabel('maxNestingDepth')}
          <Input type="number" min="5" max="200" step="1" value={config.maxNestingDepth} onChange={(event) => updateConfig(config, { maxNestingDepth: parseNumber(event.target.value, defaultParserConfig.maxNestingDepth) }, onChange)} />
        </label>
      </div>
      <label className="grid gap-1 text-sm font-medium">
        {configLabel('customInstructions')}
        <Textarea value={config.customInstructions ?? ''} onChange={(event) => updateConfig(config, { customInstructions: event.target.value.trim() || undefined }, onChange)} placeholder="Add constraints for generated forms..." />
      </label>
      <div className="grid gap-2">
        <p className="text-sm font-medium">{configLabel('systemPromptFields')}</p>
        <div className="grid gap-2 sm:grid-cols-2">
          {fieldOptions.map((field) => (
            <label key={field} className="flex items-center gap-2 rounded-md border p-2 text-xs">
              <input type="checkbox" checked={config.systemPromptFields.includes(field)} onChange={() => onChange(toggleField(config, field))} />
              {field}
            </label>
          ))}
        </div>
      </div>
      <div className="grid gap-2">
        <div className="flex items-center justify-between gap-2">
          <p className="text-sm font-medium">System prompt preview</p>
          <Button type="button" variant="outline" size="sm" onClick={() => void copySystemPrompt()}>{copied ? 'Copied' : 'Copy prompt'}</Button>
        </div>
        <pre className="max-h-64 overflow-auto rounded-md border bg-muted/30 p-3 text-xs whitespace-pre-wrap">{systemPrompt}</pre>
      </div>
    </section>
  );
}

'use client';

import { Check, Copy } from 'lucide-react';
import { useMemo, useState } from 'react';

import { Button } from '@/components/ui/button';
import { parseAiToFormedible } from '@/lib/formedible/ai-parser';
import { parseSafeStreamEvents, redactUnknown } from '@/lib/formedible/ai-safe-persistence';
import type { AiFormParseResult, AiMessage, AiStreamEvent } from '@/lib/formedible/ai-types';
import { cn } from '@/lib/utils';

export interface RawOutputPanelProps {
  readonly message: AiMessage;
  readonly className?: string;
}

type ExtractionParseStatus = 'pending' | 'parsed' | 'failed' | 'no-form';

interface RawOutputViewModel {
  readonly rawText: string;
  readonly thinkingText: string | undefined;
  readonly formCode: string | undefined;
  readonly parseResult: AiFormParseResult | undefined;
  readonly status: ExtractionParseStatus;
  readonly statusLabel: string;
  readonly statusDescription: string;
  readonly safeEvents: readonly AiStreamEvent[];
  readonly metadata: unknown;
}

interface CopyButtonProps {
  readonly value: string;
  readonly label: string;
  readonly copiedLabel?: string;
  readonly disabled?: boolean;
}

function createViewModel(message: AiMessage): RawOutputViewModel {
  const isPending = message.status === 'streaming' || message.status === 'submitted';
  const rawText = message.rawContent ?? message.content;
  const formCode = message.formCode;
  const parseResult = !isPending && formCode ? parseAiToFormedible(formCode) : undefined;
  const safeEvents = parseSafeStreamEvents(message.events ?? []);
  const metadata = redactUnknown({
    id: message.id,
    role: message.role,
    status: message.status,
    provider: message.provider,
    model: message.model,
    timestamp: message.timestamp,
    createdAt: message.createdAt,
    updatedAt: message.updatedAt,
    generation: message.generation,
  });

  if (isPending) {
    return {
      rawText,
      thinkingText: message.thinking,
      formCode,
      parseResult,
      status: 'pending',
      statusLabel: 'Pending',
      statusDescription: 'Streaming is still in progress. Form extraction and parsing run after completion.',
      safeEvents,
      metadata,
    };
  }

  if (!formCode) {
    return {
      rawText,
      thinkingText: message.thinking,
      formCode,
      parseResult,
      status: 'no-form',
      statusLabel: 'No form block',
      statusDescription: 'No lowercase formedible fenced block was extracted from this assistant message.',
      safeEvents,
      metadata,
    };
  }

  if (!parseResult?.success) {
    return {
      rawText,
      thinkingText: message.thinking,
      formCode,
      parseResult,
      status: 'failed',
      statusLabel: 'Failed',
      statusDescription: 'A formedible block was extracted, but parsing failed.',
      safeEvents,
      metadata,
    };
  }

  return {
    rawText,
    thinkingText: message.thinking,
    formCode,
    parseResult,
    status: 'parsed',
    statusLabel: 'Parsed',
    statusDescription: 'A formedible block was extracted and parsed successfully.',
    safeEvents,
    metadata,
  };
}

function stringifyDebugValue(value: unknown): string {
  return JSON.stringify(redactUnknown(value), null, 2);
}

function statusClassName(status: ExtractionParseStatus): string {
  if (status === 'pending') {
    return 'border-amber-500/40 bg-amber-500/10 text-amber-700 dark:text-amber-300';
  }

  if (status === 'parsed') {
    return 'border-emerald-500/40 bg-emerald-500/10 text-emerald-700 dark:text-emerald-300';
  }

  if (status === 'failed') {
    return 'border-destructive/40 bg-destructive/10 text-destructive';
  }

  return 'border-muted-foreground/30 bg-muted text-muted-foreground';
}

function CopyButton({ value, label, copiedLabel = 'Copied', disabled }: CopyButtonProps) {
  const [copied, setCopied] = useState(false);

  async function copyValue() {
    if (disabled || typeof navigator === 'undefined' || !navigator.clipboard) {
      return;
    }

    await navigator.clipboard.writeText(value);
    setCopied(true);
    globalThis.setTimeout(() => setCopied(false), 1200);
  }

  return (
    <Button type="button" variant="ghost" size="sm" className="h-7 gap-1 px-2" onClick={copyValue} disabled={disabled} aria-label={label}>
      {copied ? <Check className="h-3.5 w-3.5" aria-hidden="true" /> : <Copy className="h-3.5 w-3.5" aria-hidden="true" />}
      {copied ? copiedLabel : 'Copy'}
    </Button>
  );
}

function DebugBlock({ title, value, copyLabel }: { readonly title: string; readonly value: string; readonly copyLabel: string }) {
  return (
    <div className="overflow-hidden rounded-md border bg-muted/20">
      <div className="flex items-center justify-between border-b bg-muted/50 px-3 py-2">
        <h5 className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">{title}</h5>
        <CopyButton value={value} label={copyLabel} disabled={value.length === 0} />
      </div>
      <pre className="max-h-72 overflow-auto p-3 text-xs leading-relaxed">
        <code>{value || 'No data available.'}</code>
      </pre>
    </div>
  );
}

export function RawOutputPanel({ message, className }: RawOutputPanelProps) {
  const viewModel = useMemo(() => createViewModel(message), [message]);
  const parsedValue = viewModel.parseResult?.success ? stringifyDebugValue(viewModel.parseResult.formOptions) : '';
  const parseErrors = viewModel.parseResult?.success === false ? stringifyDebugValue(viewModel.parseResult.errors ?? [{ message: viewModel.parseResult.error ?? 'Parsing failed.' }]) : '';
  const eventValue = stringifyDebugValue(viewModel.safeEvents);
  const metadataValue = stringifyDebugValue(viewModel.metadata);

  return (
    <details className={cn('rounded-lg border bg-background/80', className)}>
      <summary className="flex cursor-pointer items-center justify-between gap-3 px-3 py-2 text-sm font-medium">
        <span>Raw output and debug</span>
        <span className={cn('rounded-full border px-2 py-0.5 text-xs', statusClassName(viewModel.status))}>{viewModel.statusLabel}</span>
      </summary>
      <div className="space-y-3 border-t p-3">
        <p className="text-xs text-muted-foreground">{viewModel.statusDescription}</p>

        <DebugBlock title="Raw text output" value={viewModel.rawText} copyLabel="Copy raw text output" />

        <DebugBlock
          title="Thinking output"
          value={viewModel.thinkingText ?? 'This provider did not emit thinking or reasoning chunks for this message.'}
          copyLabel="Copy thinking output"
        />

        <DebugBlock title="Extracted formedible code" value={viewModel.formCode ?? ''} copyLabel="Copy extracted formedible code" />

        {viewModel.status === 'failed' ? (
          <DebugBlock title="Parse errors" value={parseErrors} copyLabel="Copy parse errors" />
        ) : (
          <DebugBlock title="Parsed form result" value={parsedValue} copyLabel="Copy parsed form result" />
        )}

        <div className="grid gap-3 md:grid-cols-2">
          <DebugBlock title="Stream events" value={eventValue} copyLabel="Copy stream events" />
          <DebugBlock title="Metadata" value={metadataValue} copyLabel="Copy metadata" />
        </div>
      </div>
    </details>
  );
}

