export interface AiProviderFeatureSupport {
  readonly temperature: boolean;
  readonly maxTokens: boolean;
  readonly thinkingBudgetTokens: boolean;
}

export const AI_PROVIDER_FEATURE_SUPPORT = {
  openai: {
    temperature: true,
    maxTokens: true,
    thinkingBudgetTokens: false,
  },
  anthropic: {
    temperature: true,
    maxTokens: true,
    thinkingBudgetTokens: true,
  },
  openrouter: {
    temperature: true,
    maxTokens: true,
    thinkingBudgetTokens: false,
  },
} as const satisfies Record<AIProvider, AiProviderFeatureSupport>;

function assertMatchingSecrets(settings: ProviderSettings, secrets: ProviderSecrets): void {
  if (settings.provider !== secrets.provider) {
    throw new Error('Provider settings and secrets must target the same provider.');
  }
}

function assertNoUnsupportedRuntimeOptions(settings: ProviderSettings): void {
  if ('endpoint' in settings || 'baseURL' in settings) {
    throw new Error('Custom provider endpoints are not supported by the AI builder. Select OpenAI, Anthropic, or OpenRouter without endpoint/baseURL overrides.');
  }

  if (settings.provider !== 'anthropic' && 'thinkingBudgetTokens' in settings) {
    throw new Error('Thinking budget tokens are only supported for Anthropic provider settings.');
  }
}

export function createTanStackTextAdapter(settings: ProviderSettings, secrets: ProviderSecrets): AnyTextAdapter {
  assertMatchingSecrets(settings, secrets);
  assertNoUnsupportedRuntimeOptions(settings);

  if (settings.provider === 'openai') {
    return createOpenaiChat(resolveSupportedModel(settings.model, SUPPORTED_OPENAI_MODELS, DEFAULT_TANSTACK_AI_MODELS.openai), secrets.apiKey);
  }

  if (settings.provider === 'anthropic') {
    return createAnthropicChat(resolveSupportedModel(settings.model, SUPPORTED_ANTHROPIC_MODELS, DEFAULT_TANSTACK_AI_MODELS.anthropic), secrets.apiKey);
  }

  return createOpenRouterText(resolveSupportedModel(settings.model, SUPPORTED_OPENROUTER_MODELS, DEFAULT_TANSTACK_AI_MODELS.openrouter), secrets.apiKey);
}

export function createTanStackModelOptions(settings: ProviderSettings): OpenAITextProviderOptions | AnthropicTextProviderOptions | OpenRouterTextModelOptions | undefined {
  assertNoUnsupportedRuntimeOptions(settings);

  if (settings.provider !== 'anthropic' || !settings.thinkingBudgetTokens || settings.thinkingBudgetTokens <= 0) {
    return undefined;
  }

  return {
    thinking: {
      type: 'enabled',
      budget_tokens: settings.thinkingBudgetTokens,
    },
  } satisfies AnthropicTextProviderOptions;
}

function resolveSupportedModel<TModel extends string>(model: string, supportedModels: readonly TModel[], fallbackModel: TModel): TModel {
  return supportedModels.find((supportedModel) => supportedModel === model) ?? fallbackModel;
}

import type { AiErrorInfo } from '@/lib/formedible/ai-types';

export interface NormalizedAiError extends AiErrorInfo {
  readonly raw: unknown;
}

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function readStringProperty(value: unknown, key: string): string | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const property = value[key];

  return typeof property === 'string' ? property : undefined;
}

function readNestedStringProperty(value: unknown, parentKey: string, childKey: string): string | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  return readStringProperty(value[parentKey], childKey);
}

function isAbortLikeError(error: unknown): boolean {
  return readStringProperty(error, 'name') === 'AbortError' || readStringProperty(error, 'code') === 'ABORT_ERR';
}

function isAuthLikeMessage(message: string): boolean {
  return /api\s*key|auth|unauthori[sz]ed|forbidden|401|403/i.test(message);
}

function isRateLimitLikeMessage(message: string): boolean {
  return /rate\s*limit|quota|too many requests|429/i.test(message);
}

function isNetworkLikeMessage(message: string): boolean {
  return /network|failed to fetch|connection|timeout|timed out|dns|cors/i.test(message);
}

export function normalizeAiError(error: unknown): NormalizedAiError {
  const directMessage = readStringProperty(error, 'message') ?? readNestedStringProperty(error, 'error', 'message');
  const code = readStringProperty(error, 'code') ?? readNestedStringProperty(error, 'error', 'code');
  const message = directMessage ?? (typeof error === 'string' ? error : 'Unknown AI generation error.');

  if (isAbortLikeError(error)) {
    return {
      message: 'Generation was stopped.',
      code: code ?? 'aborted',
      recoverable: true,
      details: error,
      raw: error,
    };
  }

  if (isAuthLikeMessage(message)) {
    return {
      message: 'The selected provider rejected the request. Check the API key and provider settings.',
      code: code ?? 'provider-auth',
      recoverable: true,
      details: error,
      raw: error,
    };
  }

  if (isRateLimitLikeMessage(message)) {
    return {
      message: 'The selected provider rate-limited the request. Try again later or choose a different model.',
      code: code ?? 'provider-rate-limit',
      recoverable: true,
      details: error,
      raw: error,
    };
  }

  if (isNetworkLikeMessage(message)) {
    return {
      message: 'The request could not reach the selected provider. Check network access and provider availability.',
      code: code ?? 'provider-network',
      recoverable: true,
      details: error,
      raw: error,
    };
  }

  return {
    message: 'The AI provider could not complete the request. Review debug output for provider details.',
    code: code ?? 'provider-error',
    recoverable: true,
    details: error,
    raw: error,
  };
}

export function createAiConfigurationError(message: string, code: string): NormalizedAiError {
  return {
    message,
    code,
    recoverable: true,
    details: { message, code },
    raw: { message, code },
  };
}

import { chat } from '@tanstack/ai';
import type { StreamChunk } from '@tanstack/ai';

import { createTanStackModelOptions, createTanStackTextAdapter } from '@/lib/formedible/ai-adapters';
import { normalizeAiError } from '@/lib/formedible/ai-errors';
import { toTanStackMessageInputs, toTanStackSystemPrompts } from '@/lib/formedible/ai-messages';
import { extractFormCode } from '@/lib/formedible/ai-parser';
import type { AiErrorInfo, AiFinishReason, AiGenerationMetadata, AiGenerationRequest, AiGenerationResult, AiStreamEvent, AiUsageMetadata } from '@/lib/formedible/ai-types';

export interface AiStreamOptions {
  readonly abortController?: AbortController;
  readonly streamFactory?: (request: AiGenerationRequest, abortController: AbortController) => AsyncIterable<unknown>;
}

interface StreamAccumulator {
  text: string;
  thinking: string;
  textChunks: string[];
  thinkingChunks: string[];
  events: AiStreamEvent[];
  errors: AiErrorInfo[];
  finishReason?: AiFinishReason;
  usage?: AiUsageMetadata;
}

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isAiProviderErrorMessage(message: string | undefined): message is string {
  return typeof message === 'string' && message.trim().length > 0;
}

function readString(value: unknown, key: string): string | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const property = value[key];

  return typeof property === 'string' ? property : undefined;
}

function readNumber(value: unknown, key: string): number | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const property = value[key];

  return typeof property === 'number' && Number.isFinite(property) ? property : undefined;
}

function readUsage(value: unknown): AiUsageMetadata | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const usage = isRecord(value.usage) ? value.usage : value;
  const inputTokens = readNumber(usage, 'inputTokens') ?? readNumber(usage, 'promptTokens');
  const outputTokens = readNumber(usage, 'outputTokens') ?? readNumber(usage, 'completionTokens');
  const totalTokens = readNumber(usage, 'totalTokens');
  const cachedInputTokens = readNumber(usage, 'cachedInputTokens');
  const reasoningTokens = readNumber(usage, 'reasoningTokens');

  if (inputTokens === undefined && outputTokens === undefined && totalTokens === undefined && cachedInputTokens === undefined && reasoningTokens === undefined) {
    return undefined;
  }

  return {
    inputTokens,
    outputTokens,
    totalTokens,
    cachedInputTokens,
    reasoningTokens,
  };
}

function normalizeFinishReason(reason: string | undefined): AiFinishReason {
  if (reason === 'stop') {
    return 'stop';
  }

  if (reason === 'length') {
    return 'length';
  }

  if (reason === 'tool_calls' || reason === 'tool-calls') {
    return 'tool-calls';
  }

  if (reason === 'content_filter' || reason === 'content-filter') {
    return 'content-filter';
  }

  if (reason === 'abort' || reason === 'aborted') {
    return 'abort';
  }

  if (reason === 'error') {
    return 'error';
  }

  return 'unknown';
}

function toTextEvent(raw: unknown, receivedAt: number): AiStreamEvent | undefined {
  const type = readString(raw, 'type');
  const delta = readString(raw, 'delta');

  if ((type === 'TEXT_MESSAGE_CONTENT' || type === 'text-delta' || type === 'text') && delta !== undefined) {
    return { type: 'text-delta', delta, raw, receivedAt };
  }

  const content = readString(raw, 'content');

  if (type === 'text' && content !== undefined) {
    return { type: 'text-delta', delta: content, raw, receivedAt };
  }

  return undefined;
}

function toThinkingEvent(raw: unknown, receivedAt: number): AiStreamEvent | undefined {
  const type = readString(raw, 'type');
  const delta = readString(raw, 'delta');

  if ((type === 'REASONING_MESSAGE_CONTENT' || type === 'thinking-delta' || type === 'reasoning-delta') && delta !== undefined) {
    return { type: 'thinking-delta', delta, raw, receivedAt };
  }

  if (type === 'STEP_FINISHED' && delta !== undefined) {
    return { type: 'thinking-delta', delta, raw, receivedAt };
  }

  return undefined;
}

function toToolEvent(raw: unknown, receivedAt: number): AiStreamEvent | undefined {
  const type = readString(raw, 'type');

  if (type === 'TOOL_CALL_START' || type === 'TOOL_CALL_ARGS' || type === 'TOOL_CALL_END') {
    return {
      type: 'tool-call',
      tool: {
        toolCallId: readString(raw, 'toolCallId'),
        toolName: readString(raw, 'toolCallName') ?? readString(raw, 'toolName'),
        input: isRecord(raw) ? raw.input ?? raw.args : undefined,
        output: isRecord(raw) ? raw.result : undefined,
        raw,
      },
      receivedAt,
    };
  }

  if (type === 'TOOL_CALL_RESULT') {
    return {
      type: 'tool-result',
      tool: {
        toolCallId: readString(raw, 'toolCallId'),
        output: isRecord(raw) ? raw.content : undefined,
        raw,
      },
      receivedAt,
    };
  }

  return undefined;
}

function toErrorEvent(raw: unknown, receivedAt: number): AiStreamEvent | undefined {
  const type = readString(raw, 'type');

  if (type !== 'RUN_ERROR' && type !== 'error') {
    return undefined;
  }

  const error = normalizeAiError(raw);

  return {
    type: 'error',
    error: {
      message: error.message,
      code: error.code,
      recoverable: error.recoverable,
      details: error.details,
    },
    raw,
    receivedAt,
  };
}

function toFinishEvent(raw: unknown, receivedAt: number): AiStreamEvent | undefined {
  const type = readString(raw, 'type');

  if (type !== 'RUN_FINISHED' && type !== 'finish') {
    return undefined;
  }

  return {
    type: 'finish',
    finishReason: normalizeFinishReason(readString(raw, 'finishReason')),
    usage: readUsage(raw),
    raw,
    receivedAt,
  };
}

export function normalizeTanStackStreamChunk(raw: unknown, receivedAt: number = Date.now()): AiStreamEvent {
  return toTextEvent(raw, receivedAt)
    ?? toThinkingEvent(raw, receivedAt)
    ?? toToolEvent(raw, receivedAt)
    ?? toErrorEvent(raw, receivedAt)
    ?? toFinishEvent(raw, receivedAt)
    ?? { type: 'raw', event: raw, receivedAt, source: readString(raw, 'type') };
}

function createInitialAccumulator(): StreamAccumulator {
  return {
    text: '',
    thinking: '',
    textChunks: [],
    thinkingChunks: [],
    events: [],
    errors: [],
  };
}

function accumulateEvent(accumulator: StreamAccumulator, event: AiStreamEvent): void {
  accumulator.events.push(event);

  if (event.type === 'text-delta') {
    accumulator.text += event.delta;
    accumulator.textChunks.push(event.delta);
    return;
  }

  if (event.type === 'thinking-delta') {
    accumulator.thinking += event.delta;
    accumulator.thinkingChunks.push(event.delta);
    return;
  }

  if (event.type === 'error') {
    accumulator.errors.push(event.error);
    accumulator.finishReason = 'error';
    return;
  }

  if (event.type === 'finish') {
    accumulator.finishReason = event.finishReason;
    accumulator.usage = event.usage;
  }
}

function assertValidGenerationRequest(request: AiGenerationRequest): asserts request is AiGenerationRequest & { readonly providerSettings: NonNullable<AiGenerationRequest['providerSettings']>; readonly providerSecrets: NonNullable<AiGenerationRequest['providerSecrets']> } {
  if (!request.providerSettings) {
    throw new Error('Provider settings are required.');
  }

  if (!request.providerSecrets) {
    throw new Error('Provider secrets are required.');
  }

  if (request.providerSettings.provider !== request.providerSecrets.provider) {
    throw new Error('Provider settings and secrets must target the same provider.');
  }

  if (request.providerSecrets.apiKey.trim().length === 0) {
    throw new Error('API key is required for the selected provider.');
  }
}

function createTanStackStream(request: AiGenerationRequest, abortController: AbortController): AsyncIterable<StreamChunk> {
  assertValidGenerationRequest(request);

  const providerSettings = request.providerSettings;
  const providerSecrets = request.providerSecrets;
  const adapter = createTanStackTextAdapter(providerSettings, providerSecrets);

  return chat({
    adapter,
    messages: toTanStackMessageInputs(request.messages),
    systemPrompts: toTanStackSystemPrompts(request.messages, request.systemPrompt),
    temperature: providerSettings.temperature,
    maxTokens: providerSettings.maxTokens,
    modelOptions: createTanStackModelOptions(providerSettings),
    conversationId: request.conversationId,
    abortController,
  });
}

export async function* streamAiResponse(request: AiGenerationRequest, options: AiStreamOptions = {}): AsyncIterable<AiStreamEvent> {
  const abortController = options.abortController ?? new AbortController();

  try {
    const stream = options.streamFactory ? options.streamFactory(request, abortController) : createTanStackStream(request, abortController);

    for await (const chunk of stream) {
      const event = normalizeTanStackStreamChunk(chunk);
      yield event;

      if (event.type === 'error') {
        return;
      }
    }

    if (abortController.signal.aborted) {
      yield {
        type: 'finish',
        finishReason: 'abort',
        raw: abortController.signal.reason,
        receivedAt: Date.now(),
      };
    }
  } catch (error) {
    if (abortController.signal.aborted) {
      yield {
        type: 'finish',
        finishReason: 'abort',
        raw: abortController.signal.reason ?? error,
        receivedAt: Date.now(),
      };

      return;
    }

    const normalizedError = normalizeAiError(abortController.signal.aborted ? abortController.signal.reason : error);

    yield {
      type: 'error',
      error: {
        message: normalizedError.message,
        code: normalizedError.code,
        recoverable: normalizedError.recoverable,
        details: normalizedError.details,
      },
      raw: normalizedError.raw,
      receivedAt: Date.now(),
    };
  }
}

export async function collectAiGenerationResult(request: AiGenerationRequest, options: AiStreamOptions = {}): Promise<AiGenerationResult> {
  const startedAt = Date.now();
  const accumulator = createInitialAccumulator();

  for await (const event of streamAiResponse(request, options)) {
    accumulateEvent(accumulator, event);
  }

  const finishedAt = Date.now();
  const provider = request.providerSettings?.provider;
  const model = request.providerSettings?.model;
  const metadata: AiGenerationMetadata | undefined = provider && model
    ? {
        provider,
        model,
        finishReason: accumulator.finishReason,
        usage: accumulator.usage,
        startedAt,
        finishedAt,
      }
    : undefined;

  return {
    content: accumulator.text,
    finalText: accumulator.text,
    rawOutput: {
      text: accumulator.text,
      chunks: accumulator.textChunks,
      events: accumulator.events,
    },
    thinkingOutput: {
      text: accumulator.thinking,
      chunks: accumulator.thinkingChunks,
    },
    formCode: extractFormCode(accumulator.text),
    usage: accumulator.usage,
    provider,
    model,
    finishReason: accumulator.finishReason,
    errors: accumulator.errors,
    events: accumulator.events,
    metadata,
  };
}

export function isProviderEventError(event: AiStreamEvent): boolean {
  return event.type === 'error' && isAiProviderErrorMessage(event.error.message);
}

import { extractFormedibleCode, FormedibleParser } from '@/lib/formedible/formedible-parser';
import type { AiFormParseResult, AiParseError, AiParserConfig } from '@/lib/formedible/ai-types';
import type { EnhancedParserError } from '@/lib/formedible/parser-types';
import type { FormedibleFieldConfig, FormedibleFormValues, UseFormedibleOptions } from '@/lib/formedible/types';

function defaultValueForField(field: FormedibleFieldConfig<FormedibleFormValues>): unknown {
  if (field.type === 'checkbox' || field.type === 'switch') {
    return false;
  }

  if (field.type === 'number' || field.type === 'slider' || field.type === 'rating' || field.type === 'duration') {
    return 0;
  }

  if (field.type === 'multiSelect' || field.type === 'array') {
    return [];
  }

  if (field.type === 'object' || field.type === 'location') {
    return {};
  }

  return '';
}

function inferDefaultValues(options: UseFormedibleOptions<FormedibleFormValues>): UseFormedibleOptions<FormedibleFormValues> {
  const existingDefaults = options.formOptions.defaultValues;
  const defaultValues: FormedibleFormValues = { ...existingDefaults };

  for (const field of options.fields) {
    if (!Object.prototype.hasOwnProperty.call(defaultValues, field.name)) {
      defaultValues[field.name] = defaultValueForField(field);
    }
  }

  return {
    ...options,
    formOptions: {
      ...options.formOptions,
      defaultValues,
    },
  };
}

function toAiParseError(error: EnhancedParserError): AiParseError {
  return {
    message: error.message,
    field: error.location?.field,
    line: error.location?.line,
    column: error.location?.column,
    details: error,
  };
}

function errorMessage(errors: readonly EnhancedParserError[]): string | undefined {
  return errors.map((error) => error.message).join('\n') || undefined;
}

export function parseAiToFormedible(code: string, parserConfig?: AiParserConfig): AiFormParseResult {
  const result = FormedibleParser.parseAiOutput(code, {
    strictValidation: parserConfig?.strictValidation ?? true,
    allowedFieldTypes: parserConfig?.allowedFieldTypes,
    allowedKeys: parserConfig?.allowedKeys,
    allowedFieldKeys: parserConfig?.allowedFieldKeys,
    allowedPageKeys: parserConfig?.allowedPageKeys,
    allowedProgressKeys: parserConfig?.allowedProgressKeys,
    allowedFormOptionsKeys: parserConfig?.allowedFormOptionsKeys,
  });

  if (!result.success || result.config === undefined) {
    return {
      schema: undefined,
      formOptions: { fields: [], formOptions: { defaultValues: {} } },
      success: false,
      error: errorMessage(result.errors),
      errors: result.errors.map(toAiParseError),
    };
  }

  const formOptions = parserConfig?.inferDefaultValues === false ? result.config : inferDefaultValues(result.config);

  return {
    schema: formOptions.schema,
    formOptions,
    success: true,
    errors: result.errors.map(toAiParseError),
  };
}

export function extractFormCode(content: string): string | undefined {
  const extraction = extractFormedibleCode(content);

  if (extraction.code !== undefined) {
    return extraction.code;
  }

  return undefined;
}

import type { ModelMessage } from '@tanstack/ai';

import type { AiGenerationMetadata, AiMessage, AiMessagePart, AiMessageRole, AiMessageStatus, AiStreamEvent } from '@/lib/formedible/ai-types';
import { parseSafeGenerationMetadata, parseSafeMessageParts, parseSafeStreamEvents } from '@/lib/formedible/ai-safe-persistence';

export type TanStackAiMessageInput = ModelMessage<string>;

export interface PersistedAiMessage {
  readonly id: string;
  readonly role: AiMessageRole;
  readonly content: string;
  readonly rawContent?: string;
  readonly thinking?: string;
  readonly parts?: readonly AiMessagePart[];
  readonly formCode?: string;
  readonly timestamp?: number;
  readonly createdAt?: number;
  readonly updatedAt?: number;
  readonly provider?: AiMessage['provider'];
  readonly model?: string;
  readonly generation?: AiGenerationMetadata;
  readonly status?: AiMessageStatus;
  readonly events?: readonly AiStreamEvent[];
}

const AI_MESSAGE_ROLES = ['user', 'assistant', 'system'] as const satisfies readonly AiMessageRole[];
const AI_MESSAGE_STATUSES = ['idle', 'submitted', 'streaming', 'completed', 'error', 'aborted'] as const satisfies readonly AiMessageStatus[];

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isAiMessageRole(value: unknown): value is AiMessageRole {
  if (typeof value !== 'string') {
    return false;
  }

  return AI_MESSAGE_ROLES.some((role) => role === value);
}

function isAiMessageStatus(value: unknown): value is AiMessageStatus {
  if (typeof value !== 'string') {
    return false;
  }

  return AI_MESSAGE_STATUSES.some((status) => status === value);
}

function optionalString(value: unknown): string | undefined {
  return typeof value === 'string' ? value : undefined;
}

function optionalNumber(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function optionalStatus(value: unknown): AiMessageStatus | undefined {
  return isAiMessageStatus(value) ? value : undefined;
}

function toTanStackRole(role: AiMessageRole): 'user' | 'assistant' | undefined {
  if (role === 'system') {
    return undefined;
  }

  return role;
}

export function toTanStackMessageInput(message: Pick<AiMessage, 'role' | 'content'>): TanStackAiMessageInput | undefined {
  const role = toTanStackRole(message.role);

  if (!role) {
    return undefined;
  }

  return { role, content: message.content };
}

export function toTanStackMessageInputs(messages: readonly Pick<AiMessage, 'role' | 'content'>[]): TanStackAiMessageInput[] {
  return messages.flatMap((message) => {
    const input = toTanStackMessageInput(message);

    return input ? [input] : [];
  });
}

export function toTanStackSystemPrompts(messages: readonly Pick<AiMessage, 'role' | 'content'>[], explicitSystemPrompt?: string): string[] {
  const messagePrompts = messages
    .filter((message) => message.role === 'system' && message.content.trim().length > 0)
    .map((message) => message.content);

  if (explicitSystemPrompt === undefined || explicitSystemPrompt.trim().length === 0) {
    return messagePrompts;
  }

  return [explicitSystemPrompt, ...messagePrompts];
}

export function toPersistedAiMessage(message: AiMessage): PersistedAiMessage {
  const parts = parseSafeMessageParts(message.parts);
  const events = parseSafeStreamEvents(message.events);
  const generation = parseSafeGenerationMetadata(message.generation);

  return {
    id: message.id,
    role: message.role,
    content: message.content,
    rawContent: message.rawContent,
    thinking: message.thinking,
    ...(parts.length === 0 ? {} : { parts }),
    formCode: message.formCode,
    timestamp: message.timestamp,
    createdAt: message.createdAt,
    updatedAt: message.updatedAt,
    provider: message.provider,
    model: message.model,
    ...(generation ? { generation } : {}),
    status: message.status,
    ...(events.length === 0 ? {} : { events }),
  };
}

export function normalizePersistedAiMessage(value: unknown): AiMessage | undefined {
  if (!isRecord(value) || typeof value.id !== 'string' || !isAiMessageRole(value.role) || typeof value.content !== 'string') {
    return undefined;
  }

  const parts = parseSafeMessageParts(value.parts);
  const events = parseSafeStreamEvents(value.events);
  const generation = parseSafeGenerationMetadata(value.generation);

  return {
    id: value.id,
    role: value.role,
    content: value.content,
    rawContent: optionalString(value.rawContent),
    thinking: optionalString(value.thinking),
    ...(parts.length === 0 ? {} : { parts }),
    formCode: optionalString(value.formCode),
    timestamp: optionalNumber(value.timestamp),
    createdAt: optionalNumber(value.createdAt),
    updatedAt: optionalNumber(value.updatedAt),
    provider: value.provider === 'openai' || value.provider === 'anthropic' || value.provider === 'openrouter' ? value.provider : undefined,
    model: optionalString(value.model),
    ...(generation ? { generation } : {}),
    status: optionalStatus(value.status),
    ...(events.length === 0 ? {} : { events }),
  };
}

export function normalizePersistedAiMessages(values: unknown): AiMessage[] {
  if (!Array.isArray(values)) {
    return [];
  }

  return values.flatMap((value) => {
    const message = normalizePersistedAiMessage(value);

    return message ? [message] : [];
  });
}

