    ...(isDurationFormat(value.format) ? { format: value.format } : {}),
    ...(parseNumber(value.maxHours) === undefined ? {} : { maxHours: parseNumber(value.maxHours) }),
    ...(parseNumber(value.maxMinutes) === undefined ? {} : { maxMinutes: parseNumber(value.maxMinutes) }),
    ...(parseNumber(value.maxSeconds) === undefined ? {} : { maxSeconds: parseNumber(value.maxSeconds) }),
    ...(typeof value.showLabels === 'boolean' ? { showLabels: value.showLabels } : {}),
  } satisfies NonNullable<ParsedFieldConfig['durationConfig']>;

  return Object.keys(config).length === 0 ? undefined : config;
}

function parseLocationConfig(value: unknown): ParsedFieldConfig['locationConfig'] | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const defaultLocation = parseLocationValue(value.defaultLocation);
  const searchOptions = parseLocationSearchOptions(value.searchOptions);
  const config = {
    ...(defaultLocation ? { defaultLocation } : {}),
    ...(typeof value.enableSearch === 'boolean' ? { enableSearch: value.enableSearch } : {}),
    ...(typeof value.enableGeolocation === 'boolean' ? { enableGeolocation: value.enableGeolocation } : {}),
    ...(typeof value.enableManualEntry === 'boolean' ? { enableManualEntry: value.enableManualEntry } : {}),
    ...(typeof value.showMap === 'boolean' ? { showMap: value.showMap } : {}),
    ...(typeof value.searchPlaceholder === 'string' ? { searchPlaceholder: value.searchPlaceholder } : {}),
    ...(searchOptions ? { searchOptions } : {}),
  } satisfies NonNullable<ParsedFieldConfig['locationConfig']>;

  return Object.keys(config).length === 0 ? undefined : config;
}

function parseLocationValue(value: unknown): NonNullable<NonNullable<ParsedFieldConfig['locationConfig']>['defaultLocation']> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const lat = parseNumber(value.lat);
  const lng = parseNumber(value.lng);

  if (lat === undefined || lng === undefined) {
    return undefined;
  }

  return {
    lat,
    lng,
    ...(typeof value.address === 'string' ? { address: value.address } : {}),
    ...(typeof value.city === 'string' ? { city: value.city } : {}),
    ...(typeof value.state === 'string' ? { state: value.state } : {}),
    ...(typeof value.country === 'string' ? { country: value.country } : {}),
  };
}

function parseLocationSearchOptions(value: unknown): NonNullable<NonNullable<ParsedFieldConfig['locationConfig']>['searchOptions']> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const config = {
    ...(parseNumber(value.debounceMs) === undefined ? {} : { debounceMs: parseNumber(value.debounceMs) }),
    ...(parseNumber(value.minQueryLength) === undefined ? {} : { minQueryLength: parseNumber(value.minQueryLength) }),
    ...(parseNumber(value.maxResults) === undefined ? {} : { maxResults: parseNumber(value.maxResults) }),
  } satisfies NonNullable<NonNullable<ParsedFieldConfig['locationConfig']>['searchOptions']>;

  return Object.keys(config).length === 0 ? undefined : config;
}

function parseFileConfig(value: unknown): ParsedFieldConfig['fileConfig'] | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const config = {
    ...(typeof value.accept === 'string' ? { accept: value.accept } : {}),
    ...(typeof value.multiple === 'boolean' ? { multiple: value.multiple } : {}),
    ...(parseNumber(value.maxSize) === undefined ? {} : { maxSize: parseNumber(value.maxSize) }),
    ...(parseNumber(value.maxFiles) === undefined ? {} : { maxFiles: parseNumber(value.maxFiles) }),
  } satisfies NonNullable<ParsedFieldConfig['fileConfig']>;

  return Object.keys(config).length === 0 ? undefined : config;
}

function parseFieldSection(value: unknown): ParsedFieldConfig['section'] | undefined {
  if (typeof value === 'string') {
    return value;
  }

  if (!isRecord(value) || typeof value.title !== 'string') {
    return undefined;
  }

  return {
    title: value.title,
    ...(typeof value.description === 'string' ? { description: value.description } : {}),
  };
}

function parseFieldOptions(value: unknown): readonly FormedibleFieldOption[] {
  if (!Array.isArray(value)) {
    return [];
  }

  const options: FormedibleFieldOption[] = [];

  for (const entry of value) {
    if (typeof entry === 'string') {
      options.push(entry);
      continue;
    }

    if (!isRecord(entry) || typeof entry.value !== 'string' || typeof entry.label !== 'string') {
      continue;
    }

    options.push({
      value: entry.value,
      label: entry.label,
      ...(typeof entry.disabled === 'boolean' ? { disabled: entry.disabled } : {}),
      ...(typeof entry.description === 'string' ? { description: entry.description } : {}),
    });
  }

  return options;
}

function parseOptionSets(value: unknown): Readonly<Record<string, readonly FormedibleFieldOption[]>> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const entries: [string, readonly FormedibleFieldOption[]][] = [];

  for (const [key, entryValue] of Object.entries(value)) {
    const options = parseFieldOptions(entryValue);

    if (options.length > 0) {
      entries.push([key, options]);
    }
  }

  return entries.length === 0 ? undefined : Object.fromEntries(entries);
}

function parseObjectConfig(value: unknown): ParsedFieldConfig['objectConfig'] | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const fields = parseFieldConfigs(value.fields);
  const config = {
    ...(fields.length === 0 ? {} : { fields }),
    ...(value.layout === 'stack' || value.layout === 'grid' ? { layout: value.layout } : {}),
    ...(parseNumber(value.columns) === undefined ? {} : { columns: parseNumber(value.columns) }),
  } satisfies NonNullable<ParsedFieldConfig['objectConfig']>;

  return Object.keys(config).length === 0 ? undefined : config;
}

function parseArrayConfig(value: unknown): ParsedFieldConfig['arrayConfig'] | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const objectConfig = parseObjectConfig(value.objectConfig);
  const defaultValue = parseSafeJsonValue(value.defaultValue);
  const config = {
    ...(isArrayItemType(value.itemType) ? { itemType: value.itemType } : {}),
    ...(parseNumber(value.minItems) === undefined ? {} : { minItems: parseNumber(value.minItems) }),
    ...(parseNumber(value.maxItems) === undefined ? {} : { maxItems: parseNumber(value.maxItems) }),
    ...(typeof value.sortable === 'boolean' ? { sortable: value.sortable } : {}),
    ...(defaultValue === undefined ? {} : { defaultValue }),
    ...(objectConfig ? { objectConfig } : {}),
  } satisfies NonNullable<ParsedFieldConfig['arrayConfig']>;

  return Object.keys(config).length === 0 ? undefined : config;
}

function parseFormOptions(value: unknown): ParsedFormConfig['formOptions'] | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const defaultValues = parseSafeJsonRecordAllowEmpty(value.defaultValues);
  const formOptions = {
    defaultValues: defaultValues ?? {},
  } satisfies ParsedFormConfig['formOptions'];

  return formOptions;
}

function parsePages(value: unknown): NonNullable<ParsedFormConfig['pages']> {
  if (!Array.isArray(value)) {
    return [];
  }

  const pages: NonNullable<ParsedFormConfig['pages']>[number][] = [];

  for (const entry of value) {
    if (!isRecord(entry) || typeof entry.title !== 'string') {
      continue;
    }

    const page = parseNumber(entry.page);

    if (page === undefined) {
      continue;
    }

    pages.push({
      page,
      title: entry.title,
      ...(typeof entry.description === 'string' ? { description: entry.description } : {}),
      ...(typeof entry.conditional === 'string' ? { conditional: entry.conditional } : {}),
    });
  }

  return pages;
}

function parseTabs(value: unknown): NonNullable<ParsedFormConfig['tabs']> {
  if (!Array.isArray(value)) {
    return [];
  }

  const tabs: NonNullable<ParsedFormConfig['tabs']>[number][] = [];

  for (const entry of value) {
    if (typeof entry === 'string') {
      tabs.push(entry);
      continue;
    }

    if (!isRecord(entry) || typeof entry.id !== 'string' || typeof entry.label !== 'string') {
      continue;
    }

    tabs.push({
      id: entry.id,
      label: entry.label,
      ...(typeof entry.description === 'string' ? { description: entry.description } : {}),
      ...(typeof entry.conditional === 'string' ? { conditional: entry.conditional } : {}),
    });
  }

  return tabs;
}

function parseProgress(value: unknown): ParsedFormConfig['progress'] | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const progress = {
    ...(typeof value.showSteps === 'boolean' ? { showSteps: value.showSteps } : {}),
    ...(typeof value.showPercentage === 'boolean' ? { showPercentage: value.showPercentage } : {}),
  } satisfies NonNullable<ParsedFormConfig['progress']>;

  return Object.keys(progress).length === 0 ? undefined : progress;
}

function parsePersistence(value: unknown): ParsedFormConfig['persistence'] | undefined {
  if (!isRecord(value) || typeof value.key !== 'string') {
    return undefined;
  }

  const exclude = parseStringArray(value.exclude);
  const persistence = {
    key: '[REDACTED]',
    ...(value.storage === 'localStorage' || value.storage === 'sessionStorage' ? { storage: value.storage } : {}),
    ...(parseNumber(value.debounceMs) === undefined ? {} : { debounceMs: parseNumber(value.debounceMs) }),
    ...(exclude.length === 0 ? {} : { exclude }),
    ...(typeof value.restoreOnMount === 'boolean' ? { restoreOnMount: value.restoreOnMount } : {}),
  } satisfies NonNullable<ParsedFormConfig['persistence']>;

  return persistence;
}

function parseParseErrors(value: unknown): readonly AiParseError[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value.flatMap((entry) => {
    if (!isRecord(entry) || typeof entry.message !== 'string') {
      return [];
    }

    return [{
      message: redactSecretString(entry.message),
      ...(typeof entry.code === 'string' ? { code: redactSecretString(entry.code) } : {}),
      ...(typeof entry.field === 'string' ? { field: redactSecretString(entry.field) } : {}),
      ...(parseNumber(entry.line) === undefined ? {} : { line: parseNumber(entry.line) }),
      ...(parseNumber(entry.column) === undefined ? {} : { column: parseNumber(entry.column) }),
      ...(parseSafeJsonValue(entry.details) === undefined ? {} : { details: redactUnknown(entry.details) }),
    }];
  });
}

function parseConversationMetadata(value: unknown): AiConversationMetadata | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const values = parseSafeJsonRecord(value.values);

  return {
    ...(typeof value.title === 'string' ? { title: redactSecretString(value.title) } : {}),
    ...(typeof value.description === 'string' ? { description: redactSecretString(value.description) } : {}),
    ...(isAIProvider(value.activeProvider) ? { activeProvider: value.activeProvider } : {}),
    ...(typeof value.activeModel === 'string' ? { activeModel: value.activeModel } : {}),
    ...(values ? { values } : {}),
  };
}

function parseUiState(value: unknown): PersistedUiState {
  if (!isRecord(value) || typeof value.currentConversationId !== 'string') {
    return {};
  }

  return { currentConversationId: value.currentConversationId };
}

function sanitizeConversationForPersistence(conversation: AiConversation): AiConversation {
  return sanitizeConversation(conversation);
}

function sanitizeConversationForExport(conversation: AiConversation): AiConversation {
  return sanitizeConversation(conversation);
}

function sanitizeConversation(conversation: AiConversation): AiConversation {
  const parsedConversation = parseConversation(conversation);
  return parsedConversation ?? {
    id: conversation.id,
    title: conversation.title,
    messages: [],
    createdAt: conversation.createdAt,
    updatedAt: conversation.updatedAt,
  };
}

function withOptionalCurrentConversationId(state: Omit<PersistedAIBuilderState, 'currentConversationId'>, currentConversationId: string | undefined): PersistedAIBuilderState {
  return currentConversationId ? { ...state, currentConversationId } : state;
}

function removeStorageItem(key: string, area: StorageArea): void {
  if (!canUseStorage(area)) {
    return;
  }

  try {
    getStorage(area).removeItem(key);
  } catch {
    return;
  }
}

function getStorage(area: StorageArea): Storage {
  return area === 'local' ? window.localStorage : window.sessionStorage;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function parseStrictSafeJsonValue(value: unknown): AiJsonValue | undefined {
  if (value === null || typeof value === 'boolean') {
    return value;
  }

  if (typeof value === 'string') {
    return redactSecretString(value);
  }

  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : undefined;
  }

  if (Array.isArray(value)) {
    const entries: AiJsonValue[] = [];

    for (const entry of value) {
      const parsedEntry = parseStrictSafeJsonValue(entry);

      if (parsedEntry === undefined) {
        return undefined;
      }

      entries.push(parsedEntry);
    }

    return entries;
  }

  if (!isPlainJsonRecord(value)) {
    return undefined;
  }

  const entries: [string, AiJsonValue][] = [];

  for (const [key, entryValue] of Object.entries(value)) {
    if (isSecretJsonKey(key)) {
      entries.push([key, '[REDACTED]']);
      continue;
    }

    const parsedEntry = parseStrictSafeJsonValue(entryValue);

    if (parsedEntry === undefined) {
      return undefined;
    }

    entries.push([key, parsedEntry]);
  }

  return Object.fromEntries(entries);
}

function isPlainJsonRecord(value: unknown): value is Record<string, unknown> {
  if (!isRecord(value)) {
    return false;
  }

  const prototype = Object.getPrototypeOf(value) as unknown;
  return prototype === Object.prototype || prototype === null;
}

function isSecretJsonKey(key: string): boolean {
  const normalizedKey = key.toLowerCase();
  return normalizedKey === 'key'
    || normalizedKey.includes('apikey')
    || normalizedKey.includes('api_key')
    || normalizedKey.includes('secret')
    || normalizedKey.includes('token')
    || normalizedKey.includes('authorization')
    || normalizedKey.includes('password')
    || normalizedKey.includes('bearer')
    || normalizedKey.includes('credential');
}

function isAIProvider(value: unknown): value is AIProvider {
  return typeof value === 'string' && supportedProviders.some((provider) => provider === value);
}

function isAiMessageRole(value: unknown): value is AiMessageRole {
  return typeof value === 'string' && supportedRoles.some((role) => role === value);
}

function isAiMessageStatus(value: unknown): value is AiMessageStatus {
  return typeof value === 'string' && supportedStatuses.some((status) => status === value);
}

function isFormedibleFieldType(value: unknown): value is FormedibleFieldType {
  return typeof value === 'string' && supportedFieldTypes.some((fieldType) => fieldType === value);
}

function isArrayItemType(value: unknown): value is FormedibleFieldType | 'string' | 'email' {
  return value === 'string' || isFormedibleFieldType(value);
}

function isTextareaResize(value: unknown): value is NonNullable<NonNullable<ParsedFieldConfig['textareaConfig']>['resize']> {
  return value === 'none' || value === 'both' || value === 'horizontal' || value === 'vertical' || value === 'block' || value === 'inline';
}

function isColorFormat(value: unknown): value is NonNullable<NonNullable<ParsedFieldConfig['colorConfig']>['format']> {
  return value === 'hex' || value === 'rgb' || value === 'hsl';
}

function isRatingIcon(value: unknown): value is NonNullable<NonNullable<ParsedFieldConfig['ratingConfig']>['icon']> {
  return value === 'star' || value === 'heart' || value === 'thumbs';
}

function isRatingSize(value: unknown): value is NonNullable<NonNullable<ParsedFieldConfig['ratingConfig']>['size']> {
  return value === 'sm' || value === 'md' || value === 'lg';
}

function isPhoneFormat(value: unknown): value is NonNullable<NonNullable<ParsedFieldConfig['phoneConfig']>['format']> {
  return value === 'national' || value === 'international';
}

function isDurationFormat(value: unknown): value is NonNullable<NonNullable<ParsedFieldConfig['durationConfig']>['format']> {
  return value === 'hms' || value === 'hm' || value === 'ms' || value === 'hours' || value === 'minutes' || value === 'seconds';
}

function isProviderSecretStorageMode(value: unknown): value is ProviderSecretStorageMode {
  return value === 'memory' || value === 'session' || value === 'local';
}

function parseNumber(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function parseOptionalNumber(value: unknown): number | undefined {
  return value === undefined ? undefined : parseNumber(value);
}

function parseSerializableReactNode(value: unknown): string | number | undefined {
  if (typeof value === 'string') {
    return value;
  }

  return parseNumber(value);
}

function parseStringArray(value: unknown): readonly string[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value.filter((entry): entry is string => typeof entry === 'string');
}

import type {
  AIProvider,
  AiErrorInfo,
  AiFinishReason,
  AiGenerationMetadata,
  AiJsonValue,
  AiMessagePart,
  AiStreamEvent,
  AiToolChunk,
  AiUsageMetadata,
} from '@/lib/formedible/ai-types';

const supportedProviders = ['openai', 'anthropic', 'openrouter'] as const satisfies readonly AIProvider[];
const supportedFinishReasons = ['stop', 'length', 'tool-calls', 'content-filter', 'error', 'abort', 'unknown'] as const satisfies readonly AiFinishReason[];

export function parseSafeMessageParts(value: unknown): readonly AiMessagePart[] {
  if (!Array.isArray(value)) {
    return [];
  }

  const parts: AiMessagePart[] = [];

  for (const entry of value) {
    if (!isRecord(entry) || typeof entry.type !== 'string') {
      continue;
    }

    if ((entry.type === 'text' || entry.type === 'thinking') && typeof entry.text === 'string') {
      parts.push({ type: entry.type, text: redactSecretString(entry.text) });
      continue;
    }

    if (entry.type === 'tool') {
      const tool = parseSafeToolChunk(entry.tool);

      if (tool) {
        parts.push({ type: 'tool', tool });
      }

      continue;
    }

    if (entry.type === 'raw' && isSerializableUnknown(entry.value)) {
      parts.push({ type: 'raw', value: redactUnknown(entry.value) });
    }
  }

  return parts;
}

export function parseSafeStreamEvents(value: unknown): readonly AiStreamEvent[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value.flatMap((entry) => {
    const event = parseSafeStreamEvent(entry);
    return event ? [event] : [];
  });
}

export function parseSafeGenerationMetadata(value: unknown): AiGenerationMetadata | undefined {
  if (!isRecord(value) || !isAIProvider(value.provider) || typeof value.model !== 'string') {
    return undefined;
  }

  const usage = parseSafeUsageMetadata(value.usage);
  const metadata = parseSafeJsonRecord(value.metadata);

  return {
    provider: value.provider,
    model: value.model,
    ...(isAiFinishReason(value.finishReason) ? { finishReason: value.finishReason } : {}),
    ...(usage ? { usage } : {}),
    ...(parseNumber(value.startedAt) === undefined ? {} : { startedAt: parseNumber(value.startedAt) }),
    ...(parseNumber(value.finishedAt) === undefined ? {} : { finishedAt: parseNumber(value.finishedAt) }),
    ...(typeof value.requestId === 'string' ? { requestId: value.requestId } : {}),
    ...(metadata ? { metadata } : {}),
  };
}

export function redactUnknown(value: unknown): AiJsonValue {
  return parseSafeJsonValue(value) ?? null;
}

export function parseSafeJsonValue(value: unknown): AiJsonValue | undefined {
  if (value === null || typeof value === 'boolean') {
    return value;
  }

  if (typeof value === 'string') {
    return redactSecretString(value);
  }

  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : undefined;
  }

  if (Array.isArray(value)) {
    const entries: AiJsonValue[] = [];

    for (const entry of value) {
      const redactedEntry = parseSafeJsonValue(entry);

      if (redactedEntry !== undefined) {
        entries.push(redactedEntry);
      }
    }

    return entries;
  }

  if (!isRecord(value)) {
    return undefined;
  }

  const entries: [string, AiJsonValue][] = [];

  for (const [key, entryValue] of Object.entries(value)) {
    if (isSecretKey(key)) {
      entries.push([key, '[REDACTED]']);
      continue;
    }

    const redactedValue = parseSafeJsonValue(entryValue);

    if (redactedValue !== undefined) {
      entries.push([key, redactedValue]);
    }
  }

  return Object.fromEntries(entries);
}

export function parseSafeJsonRecord(value: unknown): Readonly<Record<string, AiJsonValue>> | undefined {
  const record = parseSafeJsonRecordAllowEmpty(value);

  if (!record || Object.keys(record).length === 0) {
    return undefined;
  }

  return record;
}

function parseSafeStreamEvent(value: unknown): AiStreamEvent | undefined {
  if (!isRecord(value) || typeof value.type !== 'string') {
    return undefined;
  }

  const receivedAt = parseNumber(value.receivedAt) ?? Date.now();

  if ((value.type === 'text-delta' || value.type === 'thinking-delta') && typeof value.delta === 'string') {
    return {
      type: value.type,
      delta: redactSecretString(value.delta),
      ...(isSerializableUnknown(value.raw) ? { raw: redactUnknown(value.raw) } : {}),
      receivedAt,
    };
  }

  if (value.type === 'tool-call' || value.type === 'tool-result') {
    const tool = parseSafeToolChunk(value.tool);
    return tool ? { type: value.type, tool, receivedAt } : undefined;
  }

  if (value.type === 'error') {
    const error = parseSafeErrorInfo(value.error);
    return error ? { type: 'error', error, ...(isSerializableUnknown(value.raw) ? { raw: redactUnknown(value.raw) } : {}), receivedAt } : undefined;
  }

  if (value.type === 'finish' && isAiFinishReason(value.finishReason)) {
    const usage = parseSafeUsageMetadata(value.usage);
    return { type: 'finish', finishReason: value.finishReason, ...(usage ? { usage } : {}), ...(isSerializableUnknown(value.raw) ? { raw: redactUnknown(value.raw) } : {}), receivedAt };
  }

  if (value.type === 'raw' && isSerializableUnknown(value.event)) {
    return { type: 'raw', event: redactUnknown(value.event), receivedAt, ...(typeof value.source === 'string' ? { source: value.source } : {}) };
  }

  return undefined;
}

function parseSafeToolChunk(value: unknown): AiToolChunk | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  return {
    ...(typeof value.toolCallId === 'string' ? { toolCallId: value.toolCallId } : {}),
    ...(typeof value.toolName === 'string' ? { toolName: value.toolName } : {}),
    ...(isSerializableUnknown(value.input) ? { input: redactUnknown(value.input) } : {}),
    ...(isSerializableUnknown(value.output) ? { output: redactUnknown(value.output) } : {}),
    ...(isSerializableUnknown(value.raw) ? { raw: redactUnknown(value.raw) } : {}),
  };
}

function parseSafeErrorInfo(value: unknown): AiErrorInfo | undefined {
  if (!isRecord(value) || typeof value.message !== 'string') {
    return undefined;
  }

  return {
    message: redactSecretString(value.message),
    ...(typeof value.code === 'string' ? { code: redactSecretString(value.code) } : {}),
    ...(typeof value.recoverable === 'boolean' ? { recoverable: value.recoverable } : {}),
    ...(isSerializableUnknown(value.details) ? { details: redactUnknown(value.details) } : {}),
  };
}

function parseSafeUsageMetadata(value: unknown): AiUsageMetadata | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const usage: AiUsageMetadata = {
    ...(parseNumber(value.inputTokens) === undefined ? {} : { inputTokens: parseNumber(value.inputTokens) }),
    ...(parseNumber(value.outputTokens) === undefined ? {} : { outputTokens: parseNumber(value.outputTokens) }),
    ...(parseNumber(value.totalTokens) === undefined ? {} : { totalTokens: parseNumber(value.totalTokens) }),
    ...(parseNumber(value.cachedInputTokens) === undefined ? {} : { cachedInputTokens: parseNumber(value.cachedInputTokens) }),
    ...(parseNumber(value.reasoningTokens) === undefined ? {} : { reasoningTokens: parseNumber(value.reasoningTokens) }),
  };

  return Object.keys(usage).length > 0 ? usage : undefined;
}

export function parseSafeJsonRecordAllowEmpty(value: unknown): Readonly<Record<string, AiJsonValue>> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const entries: [string, AiJsonValue][] = [];

  for (const [key, entryValue] of Object.entries(value)) {
    if (isSecretKey(key)) {
      entries.push([key, '[REDACTED]']);
      continue;
    }

    const redactedValue = parseSafeJsonValue(entryValue);

    if (redactedValue !== undefined) {
      entries.push([key, redactedValue]);
    }
  }

  return Object.fromEntries(entries);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isAIProvider(value: unknown): value is AIProvider {
  return typeof value === 'string' && supportedProviders.some((provider) => provider === value);
}

function isAiFinishReason(value: unknown): value is AiFinishReason {
  return typeof value === 'string' && supportedFinishReasons.some((finishReason) => finishReason === value);
}

function parseNumber(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function isSerializableUnknown(value: unknown): boolean {
  return value !== undefined && typeof value !== 'function' && typeof value !== 'symbol';
}

function isSecretKey(key: string): boolean {
  const normalizedKey = key.toLowerCase();
  return normalizedKey === 'key'
    || normalizedKey.includes('apikey')
    || normalizedKey.includes('api_key')
    || normalizedKey.includes('secret')
    || normalizedKey.includes('token')
    || normalizedKey.includes('authorization')
    || normalizedKey.includes('password')
    || normalizedKey.includes('bearer')
    || normalizedKey.includes('credential');
}

export function redactSecretString(value: string): string {
  return value
    .replace(/\bsk-[A-Za-z0-9_-]+\b/g, '[REDACTED]')
    .replace(/\bBearer\s+[A-Za-z0-9._~+/=-]+\b/gi, 'Bearer [REDACTED]')
    .replace(/\b(api[\s_-]?key|secret|token)\s*[:=]\s*[^\s,;"'`)}\]]+/gi, '$1=[REDACTED]');
}

import type { AiStreamEvent } from '@/lib/formedible/ai-types';

export interface AiStreamFlush {
  readonly textDelta: string;
  readonly thinkingDelta: string;
  readonly events: readonly AiStreamEvent[];
}

export type AiStreamFlushCallback = (flush: AiStreamFlush) => void;
export type AiFrameScheduler = (callback: () => void) => number;
export type AiFrameCancellation = (frameId: number) => void;

export interface AiStreamSchedulerOptions {
  readonly scheduleFrame?: AiFrameScheduler;
  readonly cancelFrame?: AiFrameCancellation;
}

function createDefaultFrameScheduler(): AiFrameScheduler {
  return (callback) => {
    if (typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function') {
      return window.requestAnimationFrame(callback);
    }

    return globalThis.setTimeout(callback, 16) as unknown as number;
  };
}

function createDefaultFrameCancellation(): AiFrameCancellation {
  return (frameId) => {
    if (typeof window !== 'undefined' && typeof window.cancelAnimationFrame === 'function') {
      window.cancelAnimationFrame(frameId);
      return;
    }

    globalThis.clearTimeout(frameId);
  };
}

export class AiStreamScheduler {
  private textBuffer = '';
  private thinkingBuffer = '';
  private readonly eventBuffer: AiStreamEvent[] = [];
  private frameId: number | undefined;
  private readonly scheduleFrame: AiFrameScheduler;
  private readonly cancelFrame: AiFrameCancellation;
  private readonly onFlush: AiStreamFlushCallback;

  constructor(onFlush: AiStreamFlushCallback, options: AiStreamSchedulerOptions = {}) {
    this.onFlush = onFlush;
    this.scheduleFrame = options.scheduleFrame ?? createDefaultFrameScheduler();
    this.cancelFrame = options.cancelFrame ?? createDefaultFrameCancellation();
  }

  enqueue(event: AiStreamEvent): void {
    this.eventBuffer.push(event);

    if (event.type === 'text-delta') {
      this.textBuffer += event.delta;
    }

    if (event.type === 'thinking-delta') {
      this.thinkingBuffer += event.delta;
    }

    this.scheduleFlush();
  }

  flushNow(): void {
    if (this.frameId !== undefined) {
      this.cancelFrame(this.frameId);
      this.frameId = undefined;
    }

    this.flush();
  }

  private scheduleFlush(): void {
    if (this.frameId !== undefined) {
      return;
    }

    this.frameId = this.scheduleFrame(() => {
      this.frameId = undefined;
      this.flush();
    });
  }

  private flush(): void {
    if (this.textBuffer.length === 0 && this.thinkingBuffer.length === 0 && this.eventBuffer.length === 0) {
      return;
    }

    const flush: AiStreamFlush = {
      textDelta: this.textBuffer,
      thinkingDelta: this.thinkingBuffer,
      events: [...this.eventBuffer],
    };

    this.textBuffer = '';
    this.thinkingBuffer = '';
    this.eventBuffer.length = 0;
    this.onFlush(flush);
  }
}

export function createAiStreamScheduler(onFlush: AiStreamFlushCallback, options?: AiStreamSchedulerOptions): AiStreamScheduler {
  return new AiStreamScheduler(onFlush, options);
}

import type { ParsedFormConfig } from '@/lib/formedible/parser-types';
